function tryStore(){try{localStorage.setItem('__itau_t','1');localStorage.removeItem('__itau_t');return true}catch(e){return false}}
function migrateLegacy(source){
 const output=eState();output.session={...output.session,...(source.session||{})};
 for(const prior of source.boards||[]){const target=output.boards.find(b=>b.id===prior.id || (prior.id==='reporting'&&b.id==='channels'));if(!target)continue;
  if(prior.id==='reporting'){
   for(const c of prior.cases||[]){const mapped=mapOldCase(c);const ix=target.cases.findIndex(x=>x.uid===mapped.uid);if(ix>=0)target.cases[ix]=mapped;else target.cases.push(mapped)}
   continue;
  }
  if(prior.scope)target.scope={...target.scope,...prior.scope};
  if(Array.isArray(prior.offers))target.offers=prior.offers.filter(o=>prior.id!=='cards'||(!/d[eé]bito propriet[aá]rio/i.test(o.title||'')&&!/Global Wallet \//i.test(o.title||''))).map(o=>({uid:o.uid||qid(),title:o.title||'',detail:o.detail||'',rules:o.rules||'',horizon:o.horizon||'A definir',nature:o.nature||'Hipótese de trabalho',status:o.status||'Em discussão'}));
  if(Array.isArray(prior.asis))target.asis=prior.asis.filter(a=>prior.id!=='cards'||a.title!=='Global Wallet').map(a=>({uid:a.uid||qid(),step:a.step||a.title||'',where:a.where||'',who:a.who||'',reference:a.reference||a.detail||'',source:a.source||''}));
  if(Array.isArray(prior.profiles))target.profiles=prior.profiles.map(p=>({uid:p.uid||qid(),group:p.group||'',needs:p.needs||'',conditions:p.conditions||''}));
  if(Array.isArray(prior.cases))target.cases=prior.cases.filter(c=>prior.id!=='cards'||!/cart[aã]o de d[eé]bito/i.test(c.title||'')).map(mapOldCase);
  if(Array.isArray(prior.blueprint))target.blueprint=prior.blueprint.map(x=>({uid:x.uid||qid(),moment:x.moment||'',client:x.client||'',clientWhere:x.clientWhere||x.channel||'',commercial:x.commercial||x.human||'',commercialWhere:x.commercialWhere||'',operations:x.operations||x.operation||'',operationsWhere:x.operationsWhere||'',systems:x.systems||'',systemsWhere:x.systemsWhere||x.systems||'',controls:x.controls||x.control||'',nature:x.nature||'Importado · validar'}));
  if(Array.isArray(prior.progress))target.progress=prior.progress.length===8?[Math.max(prior.progress[0]||0,prior.progress[3]||0),prior.progress[1]||0,Math.max(prior.progress[2]||0,prior.progress[4]||0),prior.progress[5]||0,Math.max(prior.progress[6]||0,prior.progress[7]||0)]:prior.progress.slice(0,5);
  if(Array.isArray(prior.csd))target.csd=clone(prior.csd);
  else{
   const base=target.csd.filter(x=>x.type==='Certeza');
   for(const d of prior.deps||[])base.push({uid:'risk-'+(d.uid||qid()),type:'Dúvida',title:d.title||'',detail:d.detail||'',owner:d.owner||'',priority:d.priority||'Alta',status:d.status==='Resolvida'?'Resolvida':'Aberta',action:'Alinhar com '+(d.related||'área responsável'),deadline:'',related:d.related||'',horizon:'A definir',resolution:'',source:'Dependência importada'});
   for(const d of prior.decisions||[])base.push({uid:'question-'+(d.uid||qid()),type:'Dúvida',title:d.title||'',detail:d.question||'',owner:d.owner||'',priority:d.priority||'Alta',status:d.status==='Decidida'?'Resolvida':'Aberta',action:d.nextAction||'Validar com responsável',deadline:'',related:d.related||'',horizon:d.horizon||'A definir',resolution:d.proposal||'',source:'Decisão importada'});
   target.csd=base;
  }
  if(Array.isArray(prior.notes))target.notes=prior.notes.map(n=>({...n,stage:({0:0,1:1,2:2,3:0,4:2,5:3,6:4,7:4}[n.stage]??0)}));
 }
 return output;
}
function mapOldCase(c){return {uid:c.uid||qid(),ref:c.ref||'',title:c.title||'',profiles:Array.isArray(c.profiles)?c.profiles:RELATIONS.filter(p=>(c.profile||'').toLowerCase().includes(p.toLowerCase())),audience:c.audience||c.profile||'',need:c.need||'',trigger:c.trigger||'',result:c.result||'',flow:c.flow||'',variants:c.variants||'',exception:c.exception||'',channel:c.channel||'',horizon:c.horizon||'A definir',status:c.status||'Rascunho',owner:c.owner||'',operations:c.operations||'',systems:c.systems||''}}
function normalizeState(src){if(!src||!Array.isArray(src.boards)||!src.boards.length)return null;if(src.schema===1)return migrateLegacy(src);if(src.schema!==2&&src.schema!==3)return null;const out=eState();out.session={...out.session,...src.session};for(let target of out.boards){let b=src.boards.find(x=>x.id===target.id);if(!b)continue;for(let k of ['scope','offers','asis','profiles','cases','blueprint','csd','notes','progress','summary','owners','decisions','decisionHistory','actionPlan','journeyMap'])if(b[k]!=null)target[k]=clone(b[k]);target.scope={offerDefinition:'',...target.scope};target.offers=(target.offers||[]).map(o=>({...o,eligibility:{...Object.fromEntries(RELATIONS.map(p=>[p,'A definir'])),...(o.eligibility||{})},eligibilityNotes:{...Object.fromEntries(RELATIONS.map(p=>[p,''])),...(o.eligibilityNotes||{})}}));target.csd=(target.csd||[]).map(x=>({...x,stage:x.stage??'Geral'}));target.decisions=Array.isArray(target.decisions)?target.decisions:[];target.decisionHistory=Array.isArray(target.decisionHistory)?target.decisionHistory:[];target.actionPlan=Array.isArray(target.actionPlan)?target.actionPlan:[];target.journeyMap={...clone(INITIAL.boards.find(x=>x.id===target.id).journeyMap),...(target.journeyMap||{})};target.journeyMap.steps=Array.isArray(target.journeyMap.steps)?target.journeyMap.steps:[];target.journeyMap.assignments=target.journeyMap.assignments||{};target.owners=Array.isArray(target.owners)?target.owners:[];target.progress=[0,1,2,3,4,5].map(i=>[0,1,2].includes(Number(target.progress?.[i]))?Number(target.progress[i]):0);}out.updatedAt=src.updatedAt||'';return out}
function initState(){storageOK=tryStore();let snapshot=document.getElementById('portable-state').textContent.trim();if(storageOK){try{let saved=localStorage.getItem(STORE_KEY);if(saved){const parsed=normalizeState(JSON.parse(saved));if(parsed)return parsed}}catch(e){console.warn('local data',e)}}if(snapshot){try{const parsed=normalizeState(JSON.parse(snapshot));if(parsed)return parsed}catch(e){console.warn('snapshot',e)}}if(storageOK&&instance==='base'){try{let old=localStorage.getItem('itau_offshore_workshop_v1_base');if(old){const migrated=normalizeState(JSON.parse(old));if(migrated){localStorage.setItem(STORE_KEY,JSON.stringify(migrated));return migrated}}}catch(e){console.warn('legacy storage',e)}}return eState()}
let state;
const JSON_META_KEY=STORE_KEY+'_json_file';
let jsonMeta={};try{jsonMeta=JSON.parse(localStorage.getItem(JSON_META_KEY)||'{}')}catch(e){}
let jsonFileHandle=null,knownFileHandle=null;
let jsonFileName=jsonMeta.name||'';
let jsonDirty=!!jsonMeta.dirty;
let jsonHasExport=!!jsonMeta.saved;
let jsonReconnectNeeded=false;
function writeJSONMeta(){if(!storageOK)return;try{localStorage.setItem(JSON_META_KEY,JSON.stringify({name:jsonFileName,dirty:jsonDirty,saved:jsonHasExport}))}catch(e){}}
function storeDraft(){if(storageOK)try{localStorage.setItem(STORE_KEY,JSON.stringify(state))}catch(e){storageOK=false}}
function markJSONSynchronized(name){jsonFileName=name||'novas_jornadas_offshore.json';jsonDirty=false;jsonHasExport=true;storeDraft();writeJSONMeta();updateSaveFlag()}
function save(){state.updatedAt=new Date().toISOString();jsonDirty=true;storeDraft();writeJSONMeta();updateSaveFlag()}
const boardBy=id=>state.boards.find(b=>b.id===id);
const activeBoard=()=>boardBy(view.boardId)||state.boards[0];
const openTasks=b=>(b.csd||[]).filter(x=>x.type==='Dúvida'&&x.status!=='Resolvida');
const validated=b=>v10Validated(b);
const numValidated=()=>state.boards.reduce((s,b)=>s+validated(b),0);
const numOpen=()=>state.boards.reduce((s,b)=>s+openTasks(b).length,0);
const finalDecisions=b=>(b.decisions||[]).filter(d=>d.status==='Decisão final');
const pendingDecisions=b=>(b.decisions||[]).filter(d=>d.status==='Em discussão'||d.status==='Em validação');
function completion(b){const c=b.cases||[],o=b.offers||[],asis=b.asis||[],bp=b.blueprint||[],tasks=openTasks(b),csd=b.csd||[];const checks=[
 [isFilled(b.scope.offerDefinition),!!b.scope.problem?.trim(),!!b.scope.within?.trim()&&!!b.scope.outside?.trim(),o.length>0,b.profiles?.length>=4,o.some(x=>RELATIONS.some(p=>x.eligibility?.[p]&&x.eligibility[p]!=='A definir'))],
 [asis.length>=2,asis.length>0&&asis.every(x=>isFilled(x.where)),asis.length>0&&asis.every(x=>isFilled(x.who))],
 [c.length>=2,c.some(x=>x.profiles?.length),c.length>0&&c.every(x=>isFilled(x.result)&&isFilled(x.flow)),c.some(x=>isFilled(x.exception)||isFilled(x.variants))],
 [bp.length>=2,bp.length>0&&bp.every(x=>isFilled(x.clientWhere)),bp.length>0&&bp.every(x=>isFilled(x.commercialWhere)),bp.length>0&&bp.every(x=>isFilled(x.operationsWhere)),bp.length>0&&bp.every(x=>isFilled(x.systemsWhere))],
 [csd.some(x=>x.type==='Certeza'),csd.some(x=>x.type==='Suposição'),csd.some(x=>x.type==='Dúvida'),tasks.length===0||tasks.every(x=>isFilled(x.owner)),tasks.length===0||tasks.every(x=>isFilled(x.action)),finalDecisions(b).length>0],
 [(b.actionPlan||[]).length>0,(b.actionPlan||[]).some(a=>isFilled(a.title)&&isFilled(a.owner)),(b.actionPlan||[]).some(a=>isFilled(a.deadline)),(b.actionPlan||[]).some(a=>isFilled(a.acceptance))]
 ];return {checks,perStep:checks.map(a=>Math.round(100*a.filter(Boolean).length/a.length)),ratio:Math.round(100*checks.flat().filter(Boolean).length/checks.flat().length),validated:validated(b)} }
function pill(txt,tone=''){return `<span class="pill ${tone}">${esc(txt)}</span>`}
function titleCaseKey(b){return `${b.code} · ${b.name}`}
function printOwners(b){return (b.owners||[]).join(' / ')||'Responsável a definir'}
function renderTopbar(){return `<header class="topbar"><div class="brand"><img class="brand-logo" alt="Itaú" src="${LOGO}"><div><div class="brand-name">Novas jornadas Offshore</div><div class="brand-caption">New Bank · Workshop de definição</div></div></div><div class="toptools"><div class="saved" id="save-indicator" role="status" aria-live="polite"><i></i><span>${storageOK?'Salvo neste navegador':'Exporte para salvar'}</span></div>${jsonReconnectNeeded?btn('Reconectar JSON','reconnect-json','','tiny'):''}${btn('Salvar JSON','save-json','','accent')}${btn('Modo apresentação','focus','','ghost focusbtn')}${btn('Acompanhamento','navigate','data-page="tracker"','')}<details class="dropdown"><summary class="btn dark">Arquivo <span>⌄</span></summary><div class="dropdown-panel"><button data-action="edit" data-kind="session">Configurar workshop</button><button data-action="export-portable">Exportar HTML preenchido</button><button data-action="save-json">Salvar JSON local</button><button data-action="export-json">Baixar c\u00f3pia JSON</button><button data-action="import-json">Abrir JSON local</button><button data-action="export-csv" data-what="cases">Exportar casos de uso (CSV)</button><button data-action="export-csv" data-what="csd">Exportar CSD / pendências (CSV)</button><button data-action="export-csv" data-what="actions">Exportar plano de a\u00e7\u00e3o (CSV)</button><button data-action="export-csv" data-what="progress">Exportar acompanhamento (CSV)</button><button data-action="print">Imprimir tela atual</button><button data-action="reset-all">Restaurar template</button></div></details></div></header>`}
function sidebar(){return `<aside class="sidebar"><div class="nav-caption">WORKSPACE</div><button class="nav-btn ${view.page==='overview'?'active':''}" data-action="navigate" data-page="overview"><span>⌂</span><span class="navtxt">Visão geral</span></button><button class="nav-btn ${view.page==='tracker'?'active':''}" data-action="navigate" data-page="tracker"><span>▤</span><span class="navtxt">Acompanhamento</span></button><button class="nav-btn ${view.page==='launch'?'active':''}" data-action="navigate" data-page="launch"><span>▥</span><span class="navtxt">Launch Timeline</span></button><div class="nav-caption">FRENTES DE TRABALHO</div>${state.boards.map(b=>`<button class="nav-btn ${view.page==='board'&&view.boardId===b.id?'active':''}" data-action="open-board" data-id="${esc(b.id)}"><span class="num">${b.code}</span><span class="navtxt">${esc(b.short)}<span class="tinyline">${esc(printOwners(b))}</span></span><span class="val">${validated(b)}/${STAGES.length}</span></button>`).join('')}<div class="sidebar-end">Fora do ciclo atual: Crédito e Mortgage.<br><br>As frentes são independentes; Canais atua transversalmente.</div></aside>`}
function metrics(){const avg=Math.round(state.boards.reduce((s,b)=>s+completion(b).ratio,0)/state.boards.length);return `<div class="metrics"><div class="metric"><div class="number">06</div><div class="label">Frentes neste ciclo</div></div><div class="metric"><div class="number">${avg}<small>%</small></div><div class="label">Cobertura média de campos</div></div><div class="metric"><div class="number">${numValidated()}<small>/${state.boards.length*STAGES.length}</small></div><div class="label">Etapas validadas pelos grupos</div></div><div class="metric"><div class="number">${numOpen()}</div><div class="label">Dúvidas em aberto</div></div></div>`}
function themeCard(b){const c=completion(b);return `<button class="theme-card" data-action="open-board" data-id="${b.id}" aria-label="Abrir ${esc(b.name)}"><div class="head"><span class="index">${b.code}</span>${b.pill?pill(b.pill,'orange'):pill(validated(b)+'/'+STAGES.length+' validadas')}</div><h3>${esc(b.name)}</h3><p>${esc(b.summary)}</p><div class="mini-progress"><i style="width:${c.ratio}%"></i></div><div class="card-bottom"><div><div class="owners"><b>Responsável:</b> ${esc(printOwners(b))}</div><div class="dim">${c.ratio}% dos campos · ${finalDecisions(b).length} decisões finais · ${openTasks(b).length} dúvidas</div></div><span class="card-arrow">↗</span></div></button>`}
function overview(){return `<div class="workspace"><section class="overview-hero"><div class="eyebrow">Itaú Private Bank · New Bank</div><h1>Novas jornadas <em>Offshore</em></h1><p>Um mapa único das funcionalidades do Offshore, conectado aos boards que definem ofertas, jornadas, arquitetura de serviço e decisões de implementação.</p><div class="hero-actions">${btn('Acompanhar preenchimento ↗','navigate','data-page="tracker"','dark')}${btn('Editar contexto do workshop','edit','data-kind="session"','')}</div></section>${metrics()}${renderMacroMap()}<div class="note-band"><span>ⓘ</span><span><strong>Como ler:</strong> a matriz consolida 85 funcionalidades derivadas de uma RFI com 105 requisitos. A fase é o marco do produto, não confirmação de tela entregue no app. Os mapas e suas camadas são propostas iniciais, não arquitetura ou elegibilidade aprovadas.</span></div></div>`}

const MAP_BOARD={'Abertura de conta':'onboarding','Checking & Savings':'accounts','Payments & Transfers':'payments','Cartões':'cards','Investimentos':'wealth'};
const MAP_LANES=[['client','Jornada / objetivo'],['channel','Canais e atendimento'],['orchestration','Orquestração'],['capability','Capacidades e parceiros'],['data','Dados e eventos']];
function featureBoardId(f){return MAP_BOARD[f.jornada]||''}
function releaseName(r){return r==='Atual → Day-1'?'Atual + Day-1':r}
function mapRelMatch(r,f){if(r==='Todos')return true;if(r==='Atual / Day-1')return f.marco_produto==='Day-1'||f.marco_produto.includes('Day-1');return f.marco_produto===r}
function statusColor(s){return s==='Pleno (ecossistema)'?'green':s==='Parcial'?'orange':s==='Não atende'?'red':'outline'}
function phaseClass(r){return r==='Release A'?'phase-a':r==='Release B'?'phase-b':r==='Release C'?'phase-c':r==='Release D'?'phase-d':r==='Sem fase definida'?'phase-no':'phase-day'}
function mapItemsFor(b){if(b.id==='channels')return MATRIX.items.filter(f=>['F001','F002','F006','F007','F009','F010','F011','F014','F017','F018','F022','F029','F030','F032','F034','F036','F040','F042','F045','F046','F048','F049','F055','F061','F080','F083'].includes(f.id));return MATRIX.items.filter(f=>f.jornada===({'onboarding':'Abertura de conta','accounts':'Checking & Savings','payments':'Payments & Transfers','cards':'Cartões','wealth':'Investimentos'}[b.id])&&(b.id!=='cards'||f.subjornada!=='Débito'))}
function filteredMacroItems(){return MATRIX.items.filter(f=>f.publico===view.macroAudience && mapRelMatch(view.macroRelease,f)&&(view.macroTech==='Todas'||view.macroTech===f.status_vendor)&&(!view.macroSearch||[f.funcionalidade,f.subjornada,f.rfi_ids,f.observacao].join(' ').toLowerCase().includes(view.macroSearch.toLowerCase())))}
function featureChip(f){return `<button class="matrix-feature" data-action="feature-details" data-feature="${esc(f.id)}" data-query="${esc([f.funcionalidade,f.subjornada,f.rfi_ids,f.observacao].join(' ').toLowerCase())}"><span class="mf-top"><span class="mf-id">${esc(f.id)}</span><span class="mf-phase ${phaseClass(f.marco_produto)}">${esc(releaseName(v10FeatureRelease(f)))}</span></span><strong>${esc(f.funcionalidade)}</strong><span class="mf-bottom">${pill(f.status_vendor.replace(' (ecossistema)',''),statusColor(f.status_vendor))}${f.natureza==='Hipótese de experiência'?pill('Hipótese UX','outline'):''}</span></button>`}
function mapColumnHead(j){const bid=MAP_BOARD[j],b=bid?boardBy(bid):null;return `<div class="macro-col-head"><div class="mini-kicker">${esc(j==='Crédito'||j==='Mortgage'?'RESERVADO · RELEASE C':b?'BOARD '+b.code:'CATEGORIA RFI')}</div><h3>${esc(j)}</h3>${b?`<button type="button" class="macro-open" data-action="open-board" data-id="${bid}">Abrir mapa do bloco ↗</button>`:`<span class="macro-paused">Fora do ciclo de workshop</span>`}</div>`}
function mapMacroLayer(j,layer){const bid=MAP_BOARD[j],b=bid?boardBy(bid):null;if(!b)return `<span class="empty-layer">A detalhar em outra etapa</span>`;const vals=[...new Set((b.journeyMap?.steps||[]).map(x=>(x[layer]||'').trim()).filter(Boolean))];return vals.length?`<ul>${vals.slice(0,3).map(v=>`<li>${esc(v)}</li>`).join('')}</ul><span class="layer-note">Resumo do mapa do bloco · ${vals.length} referências</span>`:`<span class="empty-layer">A definir no board</span>`}
function renderMacroMap(){const items=filteredMacroItems();return `<section class="macro-section" id="macro"><div class="macro-title"><div><div class="heading-kicker">MAPA DO TODO · FONTE RFI + DENOVO</div><h2>Matriz de funcionalidades</h2><p>Explore as funcionalidades do banco e entre na jornada detalhada de cada frente. Canais, orquestração, capacidades e dados podem ser vistos em outra lente.</p></div><div class="macro-total"><b>${MATRIX.items.length}</b><span>funcionalidades de referência</span></div></div><div class="macro-toolbar"><div class="map-switch"><button class="${view.macroMode==='features'?'on':''}" data-action="macro-mode" data-mode="features">Funcionalidades</button><button class="${view.macroMode==='layers'?'on':''}" data-action="macro-mode" data-mode="layers">Camadas do ecossistema</button></div><div class="aud-switch"><button data-action="macro-audience" data-audience="Cliente" class="${view.macroAudience==='Cliente'?'on':''}">Cliente</button><button data-action="macro-audience" data-audience="Operação / Comercial" class="${view.macroAudience!=='Cliente'?'on':''}">Comercial / operação</button></div></div><div class="map-filters"><label>Marco <select id="macro-release">${MAP_HORIZONS.map(x=>`<option value="${esc(x)}" ${view.macroRelease===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Cobertura RFI <select id="macro-tech">${['Todas','Pleno (ecossistema)','Parcial','Via terceiros','Não atende','Sem confirmação RFI'].map(x=>`<option value="${esc(x)}" ${view.macroTech===x?'selected':''}>${esc(x==='Pleno (ecossistema)'?'Pleno':x)}</option>`).join('')}</select></label><label class="search-feature">Buscar funcionalidade <input id="macro-search" value="${esc(view.macroSearch)}" type="search" placeholder="Nome, ID RFI, contexto..."></label><span class="map-results" id="matrix-count">${items.length} resultados</span>${btn('Limpar filtros','macro-clear','','tiny')}</div>${view.macroMode==='features'?`<div class="macro-scroll" tabindex="0" aria-label="Matriz de funcionalidades, rolagem horizontal"><div class="macro-columns">${MATRIX.journeys.map(j=>{const a=items.filter(f=>f.jornada===j);return `<section class="macro-column">${mapColumnHead(j)}<div class="macro-column-count"><b class="col-count">${a.length}</b> itens · ${esc(view.macroAudience)}</div><div class="macro-feature-list">${a.map(featureChip).join('')||'<div class="empty-layer">Sem itens para os filtros selecionados.</div>'}</div></section>`}).join('')}</div></div>`:`<div class="macro-scroll" tabindex="0" aria-label="Mapa macro das camadas de ecossistema"><div class="macro-layer-grid"><div class="macro-layer-head lane-label">CAMADAS</div>${MATRIX.journeys.map(j=>`<div class="macro-layer-head">${mapColumnHead(j)}</div>`).join('')}${MAP_LANES.map(([key,name])=>`<div class="lane-label"><span>${esc(name)}</span></div>${MATRIX.journeys.map(j=>`<div class="macro-layer-cell">${mapMacroLayer(j,key)}</div>`).join('')}`).join('')}</div></div>`}<div class="macro-foot"><span>${pill('Marco do produto ≠ canal pronto','orange')} ${pill('RFI = declaração do fornecedor','outline')}</span><span>Role horizontalmente para ver todos os blocos →</span></div><div class="transversal-link"><div><div class="mini-kicker">TRANSVERSAL</div><b>Canais, atendimento e integração de experiências</b><p>Atravessa todas as jornadas. Tem board próprio para estabelecer os pontos de contato e as integrações.</p></div>${btn('Abrir mapa de Canais ↗','open-board','data-id="channels"','dark')}</div></section>`}
function featureModal(id){const f=MATRIX.items.find(x=>x.id===id);if(!f)return;document.getElementById('feature-layer')?.remove();const bb=view.page==='board'&&view.step===-1?activeBoard():null;const match=bb&&mapItemsFor(bb).some(x=>x.id===f.id);const steps=bb?.journeyMap?.steps||[];const linked=match?(bb.journeyMap.assignments||{})[id]||'':'';const bid=featureBoardId(f);const el=document.createElement('div');el.className='modal-layer';el.id='feature-layer';el.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-labelledby="feature-title"><div class="modal-head"><div><div class="micro">${esc(f.id)} · ${esc(f.jornada)} · ${esc(f.subjornada)}</div><h2 id="feature-title">${esc(f.funcionalidade)}</h2><p>Registro original da matriz funcional. Vincular à etapa no mapa não equivale a aprovar a entrega.</p></div><button class="modal-close" data-action="close-feature" aria-label="Fechar">×</button></div><div class="feature-modal-body"><div class="feature-modal-tags">${pill(releaseName(f.marco_produto),'orange')}${pill(f.status_vendor,statusColor(f.status_vendor))}${pill(f.publico,'outline')}${pill(f.natureza,'outline')}</div><h3>Contexto da RFI e implementação</h3><p>${esc(f.observacao||'Sem observação adicional')}</p><div class="feature-ref"><strong>Referências:</strong> ${esc(f.rfi_ids||'Sem ID RFI direto')}<br><strong>Fonte:</strong> ${esc(f.fonte_rfi||'Matriz fornecida')}<br><strong>Canal digital:</strong> ${esc(f.expectativa_ux||'A validar')}</div>${match?`<div class="feature-assign"><label for="assign-feature-step">Vincular a uma etapa deste mapa</label><select id="assign-feature-step"><option value="">Sem vínculo</option>${steps.map(st=>`<option value="${esc(st.uid)}" ${linked===st.uid?'selected':''}>${esc(st.name)}</option>`).join('')}</select>${btn('Salvar vínculo','save-feature-link',`data-feature="${esc(id)}"`,'dark')}</div>`:bid?`<div class="feature-assign">${btn('Abrir mapa relacionado ↗','feature-go-board',`data-id="${bid}"`,'dark')}</div>`:'<div class="feature-assign">Esta categoria permanece fora do ciclo atual de workshops.</div>'}</div></div>`;document.body.appendChild(el)}
function mapCardFeatures(features){return features.map(f=>`<button class="map-fitem" data-action="feature-details" data-feature="${esc(f.id)}"><span>${esc(f.id)}</span><strong>${esc(f.funcionalidade)}</strong><span class="smallchip ${phaseClass(f.marco_produto)}">${esc(releaseName(v10FeatureRelease(f)))}</span></button>`).join('')}
function renderJourneyMap(b){const mp=b.journeyMap||{steps:[],assignments:{},status:'Rascunho'},all=mapItemsFor(b),visible=all.filter(f=>(view.mapAudience==='Todos'||view.mapAudience===f.publico)&&mapRelMatch(view.mapRelease,f)),linked=all.filter(f=>(mp.steps||[]).some(st=>st.uid===mp.assignments?.[f.id])).length,unmapped=visible.filter(f=>!mp.steps.some(st=>st.uid===mp.assignments?.[f.id]));const lanes=[['client','Jornada / resultado'],['channel','Canais'],['orchestration','Orquestração'],['capability','Capacidades'],['data','Dados']];return `<div class="journey-map-stage"><div class="map-board-top"><div><div class="eyebrow">MAPA DE SERVIÇO · ${esc(b.short)}</div><h2>Mapa da jornada</h2><p>O fluxo proposto deste bloco, com funcionalidades vinculadas à jornada e às camadas que precisam viabilizá-la. Os textos iniciais são hipóteses para validação.</p></div><div class="map-status-editor"><span class="micro">SITUAÇÃO DO MAPA</span><select id="journey-map-status" aria-label="Status do mapa">${['Rascunho','Em discussão','Validado'].map(x=>`<option ${x===mp.status?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="map-board-tools"><div class="map-board-stats">${pill(mp.steps.length+' etapas','outline')}${pill(linked+'/'+all.length+' funcionalidades vinculadas',linked===all.length?'green':'orange')}${pill(unmapped.length+' sem vínculo neste filtro','outline')}</div><div class="map-board-filters"><label>Público <select id="board-map-audience">${['Todos',...MAP_AUDIENCES].map(x=>`<option value="${esc(x)}" ${view.mapAudience===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Marco <select id="board-map-release">${MAP_HORIZONS.map(x=>`<option value="${esc(x)}" ${view.mapRelease===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label>${btn('+ Etapa','map-add-step','','dark')}</div></div><div class="journey-scroll" tabindex="0" aria-label="Mapa da jornada, role horizontalmente"><div class="journey-rows" style="--step-count:${mp.steps.length||1}"><div class="jm-corner"><span>CAMADAS</span></div>${mp.steps.map((st,i)=>`<div class="jm-step-title"><span class="step-number">${String(i+1).padStart(2,'0')}</span><h3>${esc(st.name)}</h3><div class="jm-edit-actions"><button data-action="map-move" data-id="${esc(st.uid)}" data-dir="-1" ${i===0?'disabled':''} title="Mover etapa para a esquerda">←</button><button data-action="map-move" data-id="${esc(st.uid)}" data-dir="1" ${i===mp.steps.length-1?'disabled':''} title="Mover etapa para a direita">→</button><button data-action="map-edit" data-id="${esc(st.uid)}" title="Editar etapa">Editar</button><button data-action="map-remove" data-id="${esc(st.uid)}" title="Excluir etapa">×</button></div></div>`).join('')}${lanes.map(([key,name],li)=>`<div class="jm-lane-name jm-lane-${li}"><b>${esc(name)}</b><span>${['O que precisa acontecer','Onde acontece','Como é coordenado','O que habilita','O que se registra'][li]}</span></div>${mp.steps.map(st=>`<div class="jm-cell jm-cell-${key} ${!st[key]?'is-empty':''}"><div>${st[key]?nl(st[key]):'A definir'}</div></div>`).join('')}`).join('')}<div class="jm-lane-name jm-functions"><b>Funcionalidades</b><span>Referências da matriz RFI</span></div>${mp.steps.map(st=>{const f=visible.filter(x=>mp.assignments?.[x.id]===st.uid);return `<div class="jm-cell jm-function-cell">${f.length?mapCardFeatures(f):'<span class="empty-layer">Nenhuma funcionalidade neste filtro.</span>'}</div>`}).join('')}</div></div>${unmapped.length?`<div class="unmapped-section"><div><h3>Funcionalidades ainda sem vínculo</h3><p>Clique em cada item para associar à etapa correta da jornada.</p></div><div class="unmapped-list">${mapCardFeatures(unmapped)}</div></div>`:''}<div class="map-footer-note"><strong>Interpretação:</strong> a funcionalidade veio da matriz RFI/DeNovo; a etapa e suas camadas são uma proposta editável. Vincular uma funcionalidade não confirma entrega no canal, contratação do componente ou arquitetura definitiva.${b.id==='cards'?' Este board aprofunda cartão de crédito; débito permanece visível na matriz global.':''}${b.id==='channels'?' Este mapa usa uma seleção inicial de funcionalidades transversais; o inventário completo está na home.':''}</div><div class="map-links">${btn('+ Dúvida sobre este mapa','add-csd','data-csd-type="Dúvida" data-stage="Mapa"','tiny')}${btn('Ver dúvidas e decisões ↗','step','data-index="4"','tiny')}${btn('Ver matriz completa ↗','navigate','data-page="overview"','tiny dark')}</div></div>`}

function breadcrumb(b){return `<div class="crumb"><button data-action="navigate" data-page="overview">Visão geral</button><span>›</span><span>Board ${b.code}</span></div>`}
function stageNav(b){return `<div class="stage-nav"><button class="stage-tab map-tab ${view.step===-1?'active':''}" data-action="step" data-index="-1" title="Mapa da jornada e funcionalidades"><span class="stage-index">◈</span><span><span class="stage-name">Mapa da jornada</span><span class="stage-sublabel">${esc(b.journeyMap?.status||'Rascunho')}</span></span></button>${STAGES.map((s,i)=>`<button class="stage-tab ${view.step===i?'active':''}" data-action="step" data-index="${i}" title="${esc(s.name)}"><span class="stage-index">${String(i+1).padStart(2,'0')}</span><span><span class="stage-name">${esc(s.short)}</span><span class="stage-sublabel"><i class="status-dot ${b.progress[i]===2?'done':b.progress[i]===1?'progress':''}"></i>${['A iniciar','Em construção','Validado'][b.progress[i]]}</span></span></button>`).join('')}</div>`}
function boardView(){const b=activeBoard(),c=completion(b),s=STAGES[view.step];return `<div class="workspace">${breadcrumb(b)}<div class="board-hero"><div class="board-head"><div><div class="eyebrow">BOARD ${b.code} · ${b.pill||'DEEP DIVE'}</div><h1>${esc(b.name)}</h1><p>${esc(b.summary)}</p><div class="board-meta">${pill('Responsável: '+printOwners(b),'outline')}${pill(openTasks(b).length+' dúvidas abertas')}${pill(finalDecisions(b).length+' decisões finais','green')}${pendingDecisions(b).length?pill(pendingDecisions(b).length+' em discussão','outline'):''}${b.pill?pill(b.pill,'orange'):''}${btn('Editar responsáveis','edit','data-kind="boardmeta"','tiny')}</div></div><div class="board-summary"><div class="micro">COBERTURA DE CAMPOS</div><div class="big">${c.ratio}%</div><div class="mini-progress"><i style="width:${c.ratio}%"></i></div><div class="small">${validated(b)}/${STAGES.length} etapas validadas</div></div></div></div>${stageNav(b)}${view.step===-1?renderJourneyMap(b):`<div class="section-block"><div class="stage-intro"><div><div class="eyebrow">ETAPA ${String(view.step+1).padStart(2,'0')} / ${String(STAGES.length).padStart(2,'0')}</div><h2>${esc(s.name)}</h2><p>${esc(s.description)}</p></div><div class="stage-state"><div class="dim">Preenchimento desta etapa: <b>${c.perStep[view.step]}%</b></div><select aria-label="Andamento da etapa" id="stage-progress">${['A iniciar','Em construção','Validado'].map((x,i)=>`<option value="${i}" ${b.progress[view.step]===i?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="step-layout"><main class="step-main">${[stageScope,stageASIS,stageCases,stageExperience,stageCSD,renderActionPlan][view.step](b)}${stageNotes(b)}<div class="stage-bottom">${btn('← Etapa anterior','prev-step',view.step===0?'disabled':'','') }<span class="mid">${c.perStep[view.step]}% dos campos · ${['A iniciar','Em construção','Validado'][b.progress[view.step]]}</span>${view.step===5?btn('Ver acompanhamento ↗','navigate','data-page="tracker"','dark'):btn('Próxima etapa →','next-step','','dark')}</div></main></div></div>${guide(b)}`}</div>`}
function guide(b){let s=STAGES[view.step];return `<div class="guide-widget"><button class="guide-toggle" data-action="toggle-guide" aria-expanded="${view.guideOpen?'true':'false'}" aria-controls="guide-panel"><span class="guide-icon">?</span><span>Guia de facilitação</span><span class="guide-chevron">${view.guideOpen?'×':'↗'}</span></button>${view.guideOpen?`<aside class="guide-drawer" id="guide-panel" aria-label="Guia da etapa"><div class="guide-drawer-top"><span class="micro">APOIO À FACILITAÇÃO · ETAPA ${String(view.step+1).padStart(2,'0')}</span><button data-action="toggle-guide" aria-label="Fechar guia">×</button></div><h3>Perguntas para destravar</h3><ol>${s.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ol><div class="result"><div class="micro">ENTREGÁVEL ESPERADO</div><span>${esc(s.result)}</span></div>${view.step===0&&b.focus?.length?`<details class="source-notes" style="margin-top:18px"><summary>Pontos de atenção da frente</summary><ul>${b.focus.slice(0,7).map(f=>`<li>${esc(f)}</li>`).join('')}</ul></details>`:''}</aside>`:''}</div>`}
function cardHeading(title,desc,actions=''){return `<div class="card-heading"><div><h3>${esc(title)}</h3><p>${esc(desc)}</p></div><div class="row-actions">${actions}</div></div>`}
function actEdit(kind,uid,label='Editar'){return bare(label,'edit',`data-kind="${kind}" ${uid?`data-id="${esc(uid)}"`:''}`)}
function actDelete(kind,uid){return bare('Excluir','delete',`data-kind="${kind}" data-id="${esc(uid)}" class="delete"`)}
function stageScope(b){const fields=[['Problema que queremos resolver',b.scope.problem],['Dentro do recorte',b.scope.within],['Fora do recorte',b.scope.outside],['Resultado esperado',b.scope.value]];const statuses=['A definir','Elegível','Condicional','Não elegível'];const flag=x=>x==='Elegível'?'green':x==='Condicional'?'orange':x==='Não elegível'?'red':'outline';return `<section class="canvas-card offer-definition">${cardHeading('Definição da oferta','Primeiro, descreva qual oferta queremos construir e o valor que ela entrega.',btn('Editar definição','edit','data-kind="scope"','tiny'))}<div class="definition-text ${!isFilled(b.scope.offerDefinition)?'empty':''}">${isFilled(b.scope.offerDefinition)?nl(b.scope.offerDefinition):'Qual é a proposta da oferta desta frente? Para quem ela existe e qual necessidade atende? Preencha esta síntese antes de detalhar o recorte.'}</div></section><section class="canvas-card">${cardHeading('Recorte de atuação','Delimite onde a oferta atua, o que está incluído e o que fica fora.',btn('Editar recorte','edit','data-kind="scope"','tiny'))}<div class="fields-grid">${fields.map(([label,v])=>`<div class="read-field"><div class="lbl">${esc(label)}</div><div class="val ${!isFilled(v)?'empty':''}">${isFilled(v)?nl(v):'A definir durante o workshop'}</div></div>`).join('')}</div></section><section class="canvas-card">${cardHeading('Produtos, serviços e capacidades','Os itens concretos que compõem a oferta, com regras e horizonte.',btn('+ Incluir item','edit','data-kind="offers"','tiny dark'))}<div class="offer-grid">${b.offers.map(o=>`<article class="offer-card"><div class="tags">${pill(o.horizon||'A definir',o.horizon==='Legal Day One'?'orange':'')}${pill(o.nature||'Hipótese','outline')}</div><h4>${esc(o.title)}</h4><p>${esc(o.detail)}</p><p><b>Regras:</b> ${esc(o.rules||'A definir')}</p><div class="offer-actions">${pill(o.status||'Em discussão')}<div class="row-actions">${actEdit('offers',o.uid)}${actDelete('offers',o.uid)}</div></div></article>`).join('')||'<div class="empty-box">Ainda não há itens no recorte.</div>'}</div></section><section class="canvas-card">${cardHeading('Elegibilidade por oferta e perfil','Cada item pode ter regras diferentes, com condi\u00e7\u00f5es detalhadas por perfil. A definição deve acontecer aqui, antes de detalhar os casos de uso.')}<div class="notice-info"><strong>Importante:</strong> “US Person” é uma condição regulatória que pode coexistir com IPB OFF, IPB ON ou SPEC + IP. Os exemplos não significam elegibilidade já aprovada.</div><div class="table-scroll"><table class="list-table eligibility-table"><thead><tr><th>Produto / serviço</th>${RELATIONS.map(p=>`<th>${esc(p)}</th>`).join('')}<th>Ajustar</th></tr></thead><tbody>${b.offers.map(o=>`<tr><td><strong>${esc(o.title)}</strong></td>${RELATIONS.map(p=>`<td>${pill(o.eligibility?.[p]||'A definir',flag(o.eligibility?.[p]))}${isFilled(o.eligibilityNotes?.[p])?`<div class="eligibility-detail">${nl(o.eligibilityNotes[p])}</div>`:''}</td>`).join('')}<td>${actEdit('offers',o.uid)}</td></tr>`).join('')||'<tr><td colspan="6">Inclua um produto para começar a matriz.</td></tr>'}</tbody></table></div><div class="eligibility-key">${statuses.map(x=>pill(x,flag(x))).join('')}</div></section><section class="canvas-card">${cardHeading('Necessidades e condições por grupo','Referência transversal para detalhar elegibilidade e exceções, sem repetir a definição em cada caso.')}<div class="table-scroll"><table class="list-table profile-table"><thead><tr><th>Grupo</th><th>Necessidade</th><th>Condição / atenção</th><th></th></tr></thead><tbody>${b.profiles.map(p=>`<tr><td><b>${esc(p.group)}</b></td><td>${esc(p.needs||'A definir')}</td><td>${esc(p.conditions||'A definir')}</td><td>${actEdit('profiles',p.uid)}</td></tr>`).join('')}</tbody></table></div></section>`}
function stageASIS(b){return `<section class="canvas-card">${cardHeading('Processo atual','Registre somente etapa, onde acontece e quem faz. Detalhes adicionais podem ser levados à CSD.',btn('+ Adicionar etapa','edit','data-kind="asis"','tiny dark'))}<div class="table-scroll"><table class="list-table"><thead><tr><th style="width:35%">Etapa</th><th>Onde acontece</th><th>Quem faz</th><th style="width:100px"></th></tr></thead><tbody>${b.asis.map((x,i)=>`<tr><td><b>${String(i+1).padStart(2,'0')}. ${esc(x.step)}</b></td><td>${isFilled(x.where)?esc(x.where):'<span class="weak">Preencher ambiente</span>'}</td><td>${isFilled(x.who)?esc(x.who):'<span class="weak">Definir ator</span>'}</td><td><div class="row-actions">${actEdit('asis',x.uid)}${actDelete('asis',x.uid)}</div></td></tr>`).join('')||'<tr><td colspan="4">Nenhuma etapa cadastrada.</td></tr>'}</tbody></table></div>${b.asis.some(x=>isFilled(x.reference))?`<details class="source-notes"><summary>Consultar insumos utilizados no pré-preenchimento</summary><ul>${b.asis.filter(x=>x.reference).map(x=>`<li><b>${esc(x.step)}:</b> ${esc(x.reference)}</li>`).join('')}</ul></details>`:''}</section><div class="notice-info"><strong>Critério para encerrar o AS-IS:</strong> cada etapa deve ter um ambiente e um executor identificados. Onde a informação ainda não estiver confirmada, deixe a célula vazia e crie uma dúvida na etapa de CSD.</div>`}
function relationCard(b,p){return `<article class="profile-tile ${view.caseFilter===p.group?'selected':''}"><div class="profile-label"><button data-action="filter-profile" data-id="${esc(p.group)}" aria-label="Filtrar casos de ${esc(p.group)}">${esc(p.group)} ↗</button><button class="edit-profile" data-action="edit" data-kind="profiles" data-id="${esc(p.uid)}">Editar</button></div><p>${esc(p.needs||'Necessidade a definir')}</p><div class="condition">${esc(p.conditions||'Condições a definir')}</div></article>`}
function stageCases(b){const all=b.cases.filter(c=>view.caseFilter==='Todos'||c.profiles?.includes(view.caseFilter));const filtered=all.filter(c=>([c.title,c.ref,c.need,c.audience,c.owner].join(' ').toLowerCase()).includes(view.search.toLowerCase()));return `<section class="canvas-card">${cardHeading('Casos de uso','Descreva as situações reais e vincule cada caso aos grupos aplicáveis. A elegibilidade dos produtos é definida em Oferta e recorte.',btn('+ Novo caso de uso','edit','data-kind="cases"','tiny dark'))}<div class="profile-filter" role="group" aria-label="Filtrar casos por grupo">${['Todos',...RELATIONS].map(p=>`<button class="profile-filter-button ${view.caseFilter===p?'active':''}" data-action="filter-profile" data-id="${esc(p)}">${p==='Todos'?'Todos os perfis':esc(p)}</button>`).join('')}</div><div class="filter-row"><div class="items"><span class="dim"><span id="cases-count">${filtered.length}</span> casos de uso</span></div><input type="text" class="search" id="case-search" placeholder="Buscar casos de uso" value="${esc(view.search)}" aria-label="Buscar caso de uso"></div><div class="case-list" id="case-list">${filtered.map(c=>`<article class="case-card" data-query="${esc([c.title,c.ref,c.need,c.audience,c.owner].join(' ').toLowerCase())}"><div class="case-top"><span class="micro">${esc(c.ref||'NOVO')}</span>${pill(c.horizon||'A definir',c.horizon==='Legal Day One'?'orange':'')}</div><h4>${esc(c.title)}</h4><p>${esc(c.need||c.result||'Necessidade a definir')}</p><div class="tags">${c.profiles?.length?c.profiles.map(p=>pill(p)).join(''):pill(c.audience||'Perfil a associar','outline')}</div><div class="bottom"><small>${esc(c.status||'Rascunho')} · ${esc(c.owner||'Dono a definir')}</small><div class="row-actions"><button class="button-link" data-action="edit" data-kind="cases" data-id="${esc(c.uid)}">Abrir caso →</button>${actDelete('cases',c.uid)}</div></div></article>`).join('')||'<div class="empty-box"><strong>Nenhum caso encontrado.</strong> Altere o filtro ou adicione um caso de uso.</div>'}</div></section>`}
function lane(label,where,action){return `<div class="lane"><span class="lane-label">${esc(label)}</span><span class="where-chip ${!isFilled(where)?'blank':''}">${esc(where||'Onde? A definir')}</span><p>${esc(action||'A definir')}</p></div>`}
function stageExperience(b){return `<section class="canvas-card">${cardHeading('Experiência de ponta a ponta','Cada bloco mostra o que acontece e a tag do ambiente onde aquela ação ocorre.',btn('+ Novo momento','edit','data-kind="blueprint"','tiny dark'))}<div class="notice-info"><strong>Exemplo de tags:</strong> Cliente · App White Label | Comercial · Savana | Operação · KYC / BPM | Sistemas · Finxact / T24. Os ambientes pré-preenchidos são referências ou hipóteses e precisam ser validados.</div>${b.blueprint.map((x,i)=>`<article class="blueprint-row"><div class="blueprint-title"><h4>${String(i+1).padStart(2,'0')} · ${esc(x.moment)}</h4><div class="row-actions">${actEdit('blueprint',x.uid)}${actDelete('blueprint',x.uid)}</div></div><div class="lane-grid">${lane('Cliente',x.clientWhere,x.client)}${lane('Comercial',x.commercialWhere,x.commercial)}${lane('Operação',x.operationsWhere,x.operations)}${lane('Sistemas e controles',x.systemsWhere,x.systems)}</div>${x.controls?`<div class="controls-row"><b>Regra / controle:</b> ${esc(x.controls)}</div>`:''}</article>`).join('')||'<div class="empty-box">Adicione momentos da jornada para preencher a experiência.</div>'}</section>`}
function csdCard(c){return `<article class="csd-item"><h4>${esc(c.title)}</h4><p>${esc(c.detail||'A detalhar')}</p><div class="foot"><span class="dim">${esc(c.owner||c.source||'A validar')}</span><button data-action="edit" data-kind="csd" data-id="${esc(c.uid)}">Editar ↗</button></div></article>`}
function stageCSD(b){let csd=b.csd||[],tasks=openTasks(b),decisions=(b.decisions||[]).slice().sort((a,z)=>(a.status==='Decisão final'?-1:1)-(z.status==='Decisão final'?-1:1)),history=b.decisionHistory||[],lists=['Certeza','Suposição','Dúvida'];let visible=csd.filter(x=>x.type==='Dúvida'&&(view.csdFilter==='Todas'||(view.csdFilter==='Abertas'?x.status!=='Resolvida':x.status==='Resolvida')));const statusTone=x=>x==='Decisão final'?'green':x==='Revogada'?'red':x==='Em validação'?'orange':'outline';return `<section class="canvas-card">${cardHeading('Estado das decisões','Diferencie decisões finais de hipóteses e dúvidas. Uma certeza na CSD não é, por si só, uma decisão.',btn('+ Registrar decisão','edit','data-kind="decisions"','tiny dark'))}<div class="decision-overview"><div class="decision-stat"><strong>${finalDecisions(b).length}</strong><span>Decisões finais</span></div><div class="decision-stat"><strong>${pendingDecisions(b).length}</strong><span>Em discussão / validação</span></div><div class="decision-stat"><strong>${tasks.length}</strong><span>Dúvidas abertas</span></div></div><div class="decision-list">${decisions.map(d=>`<article class="decision-item ${d.status==='Decisão final'?'final':''}"><div class="decision-top">${pill(d.status||'Em discussão',statusTone(d.status))}${pill(d.horizon||'A definir','outline')}</div><h4>${esc(d.title)}</h4>${d.detail?`<p>${nl(d.detail)}</p>`:''}${d.rationale?`<p><strong>Definição / justificativa:</strong> ${nl(d.rationale)}</p>`:''}<div class="decision-foot"><small>${esc(d.owner||'Responsável a definir')}${d.decidedAt&&d.status==='Decisão final'?' · Definida em '+new Date(d.decidedAt).toLocaleDateString('pt-BR'):''}</small><div class="row-actions">${actEdit('decisions',d.uid,'Editar / atualizar')}</div></div></article>`).join('')||'<div class="empty-box">Nenhuma decisão registrada. Use “Registrar decisão” para documentar alternativas em discussão ou uma escolha formalizada.</div>'}</div></section><section class="canvas-card">${cardHeading('Histórico de decisões','Toda criação ou alteração de uma decisão é registrada com data e status. Registros finais podem ser revogados, mas não desaparecem do histórico.')}<div class="history-timeline">${history.slice(0,35).map(h=>`<div class="history-row"><time>${new Date(h.at).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}</time><div><strong>${esc(h.title)}</strong><p>${esc(h.event)} · ${esc(h.from||'Novo')} → ${esc(h.to||'Em discussão')}${h.owner?' · '+esc(h.owner):''}</p></div></div>`).join('')||'<p class="dim">O histórico aparecerá aqui quando o grupo registrar a primeira decisão.</p>'}</div></section><section class="canvas-card">${cardHeading('Matriz CSD','Certezas de contexto, suposições não validadas e dúvidas que exigem encaminhamento.',btn('+ Novo registro CSD','edit','data-kind="csd"','tiny dark'))}<div class="csd-grid">${lists.map((type,i)=>{let rows=csd.filter(x=>x.type===type),shown=rows.slice(0,4);return `<div class="csd-column"><div class="csd-column-title"><h3>${esc(type==='Certeza'?'Certezas':type==='Suposição'?'Suposições':'Dúvidas')}</h3>${pill(rows.length+' registros')}</div>${shown.map(csdCard).join('')||'<div class="dim">Nenhum registro.</div>'}${rows.length>4?`<div class="dim">+${rows.length-4} registros na lista abaixo ou no formulário</div>`:''}<div style="margin-top:11px">${btn('+ Adicionar','add-csd',`data-csd-type="${type}" data-stage="4"`,'tiny')}</div></div>`}).join('')}</div></section><section class="canvas-card">${cardHeading('Dúvidas e próximos passos','Uma lista central de tarefas para responder perguntas, com responsáveis e datas.',`<select id="csd-filter" class="select-small" aria-label="Filtrar dúvidas">${['Abertas','Todas','Resolvidas'].map(x=>`<option ${view.csdFilter===x?'selected':''}>${x}</option>`).join('')}</select>${btn('+ Dúvida','add-csd','data-csd-type="Dúvida" data-stage="4"','tiny dark')}`)}<div class="table-scroll"><table class="list-table todo-table"><thead><tr><th style="width:33px">OK</th><th>Pergunta / ação necessária</th><th>Origem</th><th>Responsável</th><th>Prazo</th><th>Prioridade</th><th style="width:145px"></th></tr></thead><tbody>${visible.map(c=>`<tr class="${c.status==='Resolvida'?'closed':''}"><td><input type="checkbox" data-action="toggle-task" data-id="${esc(c.uid)}" ${c.status==='Resolvida'?'checked':''} aria-label="Resolver dúvida ${esc(c.title)}"></td><td><div class="question">${esc(c.title)}</div><div class="follow">${esc(c.action||c.detail||'Definir próximo passo')}</div></td><td>${esc(v10StageLabel(c.stage))}</td><td>${isFilled(c.owner)?esc(c.owner):pill('Sem responsável','red')}</td><td>${esc(c.deadline||'A definir')}</td><td>${pill(c.priority||'Média',c.priority==='Alta'?'amber':'')}</td><td><div class="row-actions">${actEdit('csd',c.uid)}${bare('Plano +','promote-csd',`data-id="${esc(c.uid)}"`)}</div></td></tr>`).join('')||'<tr><td colspan="7"><span class="dim">Nenhuma dúvida neste filtro.</span></td></tr>'}</tbody></table></div></section><div class="notice-info"><strong>Critério de decisão final:</strong> registrar quem aprovou e por que. Resolver uma dúvida na CSD não cria automaticamente uma decisão final. As validações oficiais seguem sob responsabilidade das áreas competentes.</div>`}
function renderActionPlan(b){const tasks=b.actionPlan||[],done=tasks.filter(a=>a.status==='Conclu\u00edda').length,doing=tasks.filter(a=>a.status==='Em andamento').length,pending=tasks.filter(a=>a.status!=='Conclu\u00edda'&&a.status!=='Cancelada').length;const sorted=tasks.slice().sort((a,z)=>(a.status==='Conclu\u00edda'?1:0)-(z.status==='Conclu\u00edda'?1:0));return `<section class="canvas-card action-plan-section">${cardHeading('Plano de a\u00e7\u00e3o','Transforme as discuss\u00f5es em entregas concretas. Cada a\u00e7\u00e3o tem respons\u00e1vel, prazo, status e crit\u00e9rio de conclus\u00e3o.',btn('+ Nova a\u00e7\u00e3o','edit','data-kind="actionPlan"','tiny dark'))}<div class="plan-summary">${pill(pending+' em aberto','orange')}${pill(doing+' em andamento')}${pill(done+' conclu\u00eddas','green')}</div><div class="action-list">${sorted.map(a=>`<article class="action-item ${a.status==='Conclu\u00edda'?'completed':''}"><div class="action-top"><div class="action-check"><input type="checkbox" data-action="toggle-plan" data-id="${esc(a.uid)}" ${a.status==='Conclu\u00edda'?'checked':''} aria-label="Marcar a\u00e7\u00e3o ${esc(a.title)} como conclu\u00edda"></div><div class="action-content"><div class="action-tags">${pill(a.status||'N\u00e3o iniciada',a.status==='Conclu\u00edda'?'green':a.status==='Aguardando defini\u00e7\u00e3o'?'orange':'outline')}${pill(a.priority||'M\u00e9dia',a.priority==='Alta'?'amber':'')}${pill(a.horizon||'A definir','outline')}</div><h4>${esc(a.title)}</h4>${a.detail?`<p>${nl(a.detail)}</p>`:''}${a.acceptance?`<p class="action-acceptance"><strong>Conclu\u00eddo quando:</strong> ${nl(a.acceptance)}</p>`:''}${a.source?`<p class="action-origin">Origem: ${esc(a.source)}</p>`:''}<div class="action-meta"><span><b>Respons\u00e1vel:</b> ${esc(a.owner||'A definir')}</span><span><b>Prazo:</b> ${esc(a.deadline?new Date(a.deadline+'T12:00:00').toLocaleDateString('pt-BR'):'A definir')}</span></div></div><div class="row-actions">${actEdit('actionPlan',a.uid)}${actDelete('actionPlan',a.uid)}</div></div></article>`).join('')||'<div class="empty-box">Nenhuma a\u00e7\u00e3o registrada. Crie tarefas a partir das discuss\u00f5es, d\u00favidas e decis\u00f5es que precisam ser implementadas.</div>'}</div></section>`}
function stageNotes(b){const notes=(b.notes||[]).filter(n=>n.stage===view.step),questions=view.step===4?[]:(b.csd||[]).filter(x=>x.type==='D\u00favida'&&String(x.stage)===String(view.step));const questionsHTML=view.step===4?'':`<div class="meeting-subhead"><h4>D\u00favidas deste bloco</h4>${btn('+ Nova d\u00favida','add-csd',`data-csd-type="D\u00favida" data-stage="${view.step}"`,'tiny dark')}</div><div class="meeting-list">${questions.map(x=>`<article class="meeting-entry"><div class="meeting-head">${pill(x.status==='Resolvida'?'Resolvida':'Em aberto',x.status==='Resolvida'?'green':'orange')}${pill(x.priority||'M\u00e9dia','outline')}<span>${esc(x.owner||'Sem respons\u00e1vel')}</span></div><h4>${esc(x.title)}</h4><p>${nl(x.action||x.detail||'Pr\u00f3ximo passo a definir')}</p><div class="row-actions">${actEdit('csd',x.uid,'Editar / responder')}</div></article>`).join('')||'<p class="dim">Nenhuma d\u00favida cadastrada para este bloco.</p>'}</div>`;return `<section class="canvas-card meeting-records">${cardHeading(view.step===4?'Anota\u00e7\u00f5es da sess\u00e3o':'D\u00favidas e anota\u00e7\u00f5es',view.step===4?'Observa\u00e7\u00f5es sobre as defini\u00e7\u00f5es, d\u00favidas e a\u00e7\u00f5es consolidadas.':'D\u00favidas registradas na CSD e anota\u00e7\u00f5es ligadas a esta etapa.')} ${questionsHTML}${view.step===4?'':`<div class="meeting-subhead notes-subhead"><h4>Anota\u00e7\u00f5es da sess\u00e3o</h4></div>`}<div class="meeting-list">${notes.map(n=>`<article class="meeting-entry"><div class="meeting-head">${pill('Anota\u00e7\u00e3o','outline')}<span>${esc(n.ts||'')}</span></div><p>${nl(n.text)}</p><div class="row-actions"><button type="button" class="bare-btn delete" data-action="delete-note" data-id="${esc(n.uid)}">Excluir</button></div></article>`).join('')||'<p class="dim">Nenhuma anota\u00e7\u00e3o registrada nesta etapa.</p>'}</div><form class="note-compose" id="note-form"><textarea name="note" required placeholder="Registre o contexto, coment\u00e1rios ou observa\u00e7\u00f5es da discuss\u00e3o..."></textarea><button type="submit" class="btn">Registrar nota</button></form></section>`}

const LAUNCH=JSON.parse(document.getElementById('launch-data').textContent);
const LAUNCH_PHASES=['Todos','Day-1','Release A','Release B','Release C','Release D'];
const LAUNCH_PCT={'Day-1':28,'Release A':42.4,'Release B':56.8,'Release C':71.2,'Release D':85.6};
const LAUNCH_PALETTE={
 'Day-1':{tone:'#203d60',light:'#eaf0f6',darktone:'#203d60'},
 'Release A':{tone:'#b8925a',light:'#f8f1e7',darktone:'#6c4d25'},
 'Release B':{tone:'#4a6b8a',light:'#ebf1f6',darktone:'#345271'},
 'Release C':{tone:'#82786e',light:'#f2efec',darktone:'#5f544a'},
 'Release D':{tone:'#2e6b57',light:'#e9f4ef',darktone:'#1d5442'}
};
function launchTone(x){const s=LAUNCH_PALETTE[x.phase]||LAUNCH_PALETTE['Day-1'];return `--tone:${s.tone};--light:${s.light};--darktone:${s.darktone}`}
function launchProducts(item){
 if(item.kind==='integration')return `<div class="lt-no-items">Este marco corresponde a uma integração, e não a um produto adicional na prateleira. O escopo detalhado de contas, dados e transações será definido no aprofundamento.</div>`;
 if(!item.products.length)return `<div class="lt-no-items">O inventário não apresenta uma lista de componentes para este item.</div>`;
 if(item.kind==='existing'){
  const categories=[...new Set(item.products.map(x=>x.category))];
  return `<div class="lt-products">${categories.map(cat=>{const rows=item.products.filter(x=>x.category===cat),groups=[...new Set(rows.map(x=>x.group))];return `<details class="lt-cat"><summary><strong>${esc(cat)}</strong><span>${rows.length} produtos</span></summary><div class="lt-catalog-body">${groups.map(group=>`<div class="lt-subgroup-name">${esc(group)}</div>${rows.filter(x=>x.group===group).map(p=>`<div class="lt-prod-row"><span>${esc(p.name)}</span>${p.outsourced?`<span class="tiny-tag outsourced">${esc(p.outsourced)}</span>`:''}${p.platform?`<span class="tiny-tag">${esc(p.platform)}</span>`:''}</div>`).join('')}`).join('')}</div></details>`}).join('')}</div>`;
 }
 return item.products.map(p=>`<div class="lt-single-prod"><div><strong>${esc(p.name)}</strong><p>${esc(p.category)} · ${esc(p.group)}</p></div><div class="lt-tags">${p.platform?pill(p.platform,'outline'):''}${p.outsourced?pill(p.outsourced,'outline'):''}</div></div>`).join('');
}
function launchFunctions(item){const rows=item.featureIds.map(id=>MATRIX.items.find(x=>x.id===id)).filter(Boolean);
 return rows.length?['Cliente','Operação / Comercial'].map(aud=>{const group=rows.filter(x=>x.publico===aud);return group.length?`<div class="lt-feature-group"><div class="lt-feature-label">${esc(aud)} · ${group.length} funcionalidades relacionadas</div><div class="lt-features">${group.map(f=>`<button class="lt-feature" type="button" data-action="feature-details" data-feature="${esc(f.id)}"><span class="lt-feature-id">${esc(f.id)}</span><span class="lt-feature-body"><strong>${esc(f.funcionalidade)}</strong><span>${esc(f.subjornada)} · ${esc(f.rfi_ids||'Sem código RFI direto')} · ${esc(releaseName(v10FeatureRelease(f)))}</span></span>${pill(f.status_vendor.replace(' (ecossistema)',''),statusColor(f.status_vendor))}<span class="lt-arrow">↗</span></button>`).join('')}</div></div>`:''}).join(''):`<div class="lt-no-items">Não há funcionalidades vinculadas a este item na matriz de referência.</div>`;
}
function launchDetails(item){const catalogCount=item.products.length,relatedCount=item.featureIds.length;
 return `<div class="lt-expand"><div class="lt-expand-head"><div><div class="heading-kicker">DETALHE DO MARCO · ${esc(item.phase)}</div><h3>O que contempla: ${esc(item.name)}</h3><p>${esc(item.note)}</p></div><div class="lt-tags">${pill(item.kind==='existing'?'Oferta atual':item.kind==='integration'?'Integração':'Novo produto','outline')}${catalogCount?pill(catalogCount+' produto'+(catalogCount>1?'s':''),'outline'):''}${pill(relatedCount+' funcionalidades relacionadas','orange')}</div></div>${item.sourceNote?`<div class="lt-no-phase-note"><b>Atenção:</b> ${esc(item.sourceNote)}</div>`:''}<div class="lt-section-title">${item.kind==='integration'?'Escopo da integração':'Produtos do inventário'}</div><p class="lt-section-sub">Nomes, classificações e marcos extraídos do documento DeNovo. ${item.kind==='existing'?'Abra as categorias abaixo para consultar os 61 produtos atuais.':''}</p>${launchProducts(item)}<div class="lt-section-title">Funcionalidades relacionadas na RFI</div><p class="lt-section-sub">Associação temática aos registros da matriz funcional; não é confirmação de entrega do canal nem lista homologada de requisitos do lançamento.</p>${launchFunctions(item)}<div class="lt-item-actions">${item.board?btn('Abrir board relacionado ↗','launch-open-board',`data-id="${esc(item.board)}"`,'tiny dark'):pill('Sem board dedicado neste ciclo','outline')}${btn('Ver funcionalidades na matriz','launch-open-matrix',`data-phase="${esc(item.phase)}"`,'tiny')}</div></div>`;
}
function launchEntry(item,index,rows){const at=LAUNCH_PCT[item.phase]||28,isFirst=index===0||rows[index-1].phase!==item.phase,preptbd=item.prep==='tbd';let subtitle=item.kind==='existing'?'61 produtos na oferta atual':item.kind==='integration'?'Integração · contas Avenue':item.kind==='product'?'Nova oferta prevista':'';
 return `<details class="lt-entry ${isFirst?'break-before':''}" style="${launchTone(item)}" data-launch-id="${esc(item.id)}"><summary><div class="lt-namebox"><span class="lt-dot"></span><div class="lt-nameinfo"><strong>${esc(item.name)}</strong><small>${esc(subtitle)}</small></div><span class="lt-openicon" aria-hidden="true">⌄</span></div><div class="lt-track">${[0,28,42.4,56.8,71.2,85.6,100].map(n=>`<i class="lt-vline" style="left:${n}%"></i>`).join('')}<div class="lt-prep ${preptbd?'tbd':''}" style="width:${Math.max(at-1,5)}%">${preptbd?'Preparação a definir':'Prep Work'}</div><div class="lt-marker" style="left:calc(${at}% + 3px);width:calc(14.4% - 8px)">${item.kind==='existing'?'Current Suite':item.kind==='integration'?'Integração':'Launch'}</div></div></summary>${launchDetails(item)}</details>`;
}
function renderLaunchTimeline(){const rows=LAUNCH.items.filter(x=>view.launchFilter==='Todos'||view.launchFilter===x.phase),counts=Object.fromEntries(LAUNCH_PHASES.slice(1).map(p=>[p,LAUNCH.items.filter(x=>x.phase===p).length]));return `<div class="workspace lt-page"><section class="lt-hero"><div class="eyebrow">DeNovo Bank Program · Product Roadmap</div><h1>Launch <em>Timeline</em></h1><p>Visão indicativa da evolução dos produtos. Abra cada lançamento para consultar o inventário associado e as funcionalidades relacionadas na RFI, com referência direta aos mapas das jornadas.</p></section><div class="lt-metrics"><div class="lt-metric"><strong>${LAUNCH.items.length}</strong><span>marcos e itens na timeline</span></div><div class="lt-metric"><strong>${LAUNCH.clientCurrentCount}</strong><span>produtos da oferta atual no catálogo</span></div><div class="lt-metric"><strong>9 + 1</strong><span>novos produtos/serviços + integração Avenue</span></div></div><div class="lt-section-hd"><div><div class="heading-kicker">EVOLUÇÃO DA OFERTA · INDICATIVA</div><h2>Planejamento de lançamentos</h2><p>Mesmo recorte do arquivo fornecido: Today / Now, Day-1 e Releases A a D. Os grupos podem ser expandidos sem perder a visão resumida.</p></div><div class="lt-actions"><label for="launch-filter">Marco <select id="launch-filter">${LAUNCH_PHASES.map(p=>`<option value="${esc(p)}" ${view.launchFilter===p?'selected':''}>${esc(p==='Todos'?'Todos os marcos':p)}${p!=='Todos'?` · ${counts[p]}`:''}</option>`).join('')}</select></label>${btn('Expandir tudo','launch-expand','','tiny')}${btn('Recolher tudo','launch-collapse','','tiny')}</div></div><section class="lt-timeline-card"><div class="lt-scroll" role="region" aria-label="Timeline de produtos (rolagem horizontal)"><div class="lt-rail"><div class="lt-phase-head"><div class="lt-labelhead">Produto / Serviço</div><div class="lt-phases">${[['Today · Now',''],['Day-1','phase-day'],['Release A','phase-a'],['Release B','phase-b'],['Release C','phase-c'],['Release D','phase-d']].map(([p,cl])=>`<div class="lt-phase ${cl?'future '+cl:''}">${esc(p)}</div>`).join('')}</div></div>${rows.map((item,i)=>launchEntry(item,i,rows)).join('')||'<p class="lt-no-items">Nenhum lançamento nesse marco.</p>'}</div></div><div class="lt-legend"><span><i class="dashed"></i>Preparação indicada no documento</span><span><i></i>Lançamento de produto / integração</span><span>Expandir <b>⌄</b> para ver o que o item contempla</span></div></section><div class="lt-note"><span>ⓘ</span><div><b>Importante sobre os marcos</b><p>A timeline é indicativa e não contém datas para Day-1 ou Releases A–D. Os espaçamentos são ilustrativos. “Prep Work” e “Preparação a definir” reproduzem o estado do documento, sem representar um lead time confirmado. Funcionalidade coberta pela RFI não significa experiência pronta no aplicativo. O conteúdo expandido combina o inventário de produtos do documento fornecido com associações à matriz já presente neste workspace.</p></div></div><div class="lt-smallprint">Fontes: DeNovo_Products_and_Launch_Timeline_v24(1).html · Matriz_Funcionalidades_Offshore_DeNovo_Finxact(3).html. Nenhum marco foi convertido em data de calendário.</div></div>`}

function tracker(){let boards=state.boards.filter(b=>view.ownerFilter==='Todos'||b.owners.includes(view.ownerFilter)),allOwners=[...new Set(state.boards.flatMap(b=>b.owners))].sort((a,b)=>a.localeCompare(b,'pt-BR'));const avg=Math.round(state.boards.reduce((n,b)=>n+completion(b).ratio,0)/state.boards.length);let noOwner=state.boards.flatMap(b=>openTasks(b)).filter(d=>!isFilled(d.owner)).length;let crit=state.boards.flatMap(b=>openTasks(b).filter(x=>x.priority==='Alta').map(x=>({...x,board:b.name,boardId:b.id}))).slice(0,9);return `<div class="workspace"><div class="tracker-hero"><div class="eyebrow">Visão transversal</div><h1>Acompanhamento de<br>preenchimento.</h1><p>Compare cobertura de informações, etapas validadas, decisões finais e dúvidas em aberto. Os indicadores são distintos: preencher não significa aprovar.</p></div><div class="kpi-cells"><div class="kpi"><strong>${avg}%</strong><span>Campos preenchidos, em média</span></div><div class="kpi"><strong>${numValidated()}/${state.boards.length*STAGES.length}</strong><span>Etapas validadas</span></div><div class="kpi"><strong>${state.boards.reduce((n,b)=>n+finalDecisions(b).length,0)}</strong><span>Decisões finais registradas</span></div><div class="kpi"><strong>${numOpen()}</strong><span>Dúvidas em aberto · ${noOwner} sem responsável</span></div></div><div class="section-heading"><div><div class="heading-kicker">POR FRENTE</div><h2>Progresso de cada board</h2></div><div><label class="dim" for="owner-filter">Responsável&nbsp;</label><select class="select-small" id="owner-filter">${['Todos',...allOwners].map(x=>`<option ${view.ownerFilter===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div></div><div class="tracker-area"><div class="table-scroll"><table class="tracker-table"><thead><tr><th>Frente</th><th>Responsável</th><th>Cobertura de campos</th><th>Etapas validadas</th><th>Mapa da jornada</th><th>Casos de uso</th><th>Decisões finais</th><th>Dúvidas abertas</th></tr></thead><tbody>${boards.map(b=>{let c=completion(b);return `<tr><td class="title"><button data-action="open-board" data-id="${b.id}">${esc(b.name)} ↗</button></td><td>${esc(printOwners(b))}</td><td><b>${c.ratio}%</b><div class="bar"><span style="width:${c.ratio}%"></span></div></td><td><b>${c.validated}/${STAGES.length}</b><div class="bar gray"><span style="width:${c.validated/STAGES.length*100}%"></span></div></td><td>${esc(b.journeyMap?.status||'Rascunho')}<br><span class="dim">${mapItemsFor(b).filter(f=>(b.journeyMap?.steps||[]).some(st=>st.uid===b.journeyMap?.assignments?.[f.id])).length}/${mapItemsFor(b).length} vínculos</span></td><td>${b.cases.length}</td><td>${finalDecisions(b).length}</td><td>${openTasks(b).length}</td></tr>`}).join('')}</tbody></table></div></div><div class="note-band"><span>ⓘ</span><span><strong>Critério de cálculo:</strong> a cobertura inclui oferta, recorte, elegibilidade, AS-IS, casos, experiência, CSD e plano de ação. A validação é manual. Uma decisão final tem registro com responsável e justificativa, independente da CSD.</span></div><div class="track-bottom"><section class="track-panel"><div class="heading-kicker">RESPONSÁVEIS</div><h3>Distribuição de frentes</h3>${allOwners.map(o=>{let assigned=state.boards.filter(b=>b.owners.includes(o));let n=assigned.reduce((x,b)=>x+validated(b),0);let max=assigned.length*STAGES.length;return `<div class="owner-row"><span class="owner-initial">${esc(o.slice(0,1))}</span><div><div class="name">${esc(o)}</div><div class="role">${assigned.map(b=>b.short).join(' · ')}</div></div><div class="amount">${n}/${max} etapas</div></div>`}).join('')}</section><section class="track-panel"><div class="heading-kicker">BLOQUEIOS DE DEFINIÇÃO</div><h3>Dúvidas prioritárias</h3>${crit.map(x=>`<div class="issue-row"><span class="type">ALTA</span><div><h4>${esc(x.title)}</h4><p>${esc(x.board)} · ${esc(x.owner||'Sem responsável')}</p></div><button data-action="jump-csd" data-board="${x.boardId}" data-id="${esc(x.uid)}">Abrir ↗</button></div>`).join('')||'<div class="dim">Não há dúvidas abertas de alta prioridade.</div>'}</section></div></div>`}
function render(keepScroll=false){let y=keepScroll?window.scrollY:0;app.className=view.focus?'focus':'';app.innerHTML=renderTopbar()+`<div class="shell">${sidebar()}<main class="main" id="workspace-main" tabindex="-1">${view.page==='board'?boardView():view.page==='tracker'?tracker():view.page==='launch'?renderLaunchTimeline():overview()}</main></div>`;updateSaveFlag();if(keepScroll)window.scrollTo(0,y)}
function updateSaveFlag(){let indicator=document.querySelector('#save-indicator'),span=indicator?.querySelector('span');if(!span)return;let txt=jsonDirty?'Altera\u00e7\u00f5es pendentes no JSON':jsonFileHandle?`JSON sincronizado \u00b7 ${jsonFileName}`:jsonHasExport?`Cópia JSON gerada: ${jsonFileName}`:storageOK?'Rascunho no navegador':'Clique em Salvar JSON';span.textContent=txt;span.title=txt;indicator.classList.toggle('unsaved',jsonDirty)}
function toast(msg){document.querySelectorAll('.toast').forEach(x=>x.remove());let n=document.createElement('div');n.className='toast';n.setAttribute('role','status');n.textContent=msg;document.body.appendChild(n);setTimeout(()=>n.remove(),3500)}
function fieldsFor(kind,rec){const t=(key,label,full=false,type='text',options=null)=>({key,label,full,type,options});switch(kind){
case 'session':return [t('title','Nome do workshop',true),t('date','Data da sessão'),t('facilitator','Facilitador'),t('participants','Participantes',true,'textarea'),t('objective','Objetivo da sessão',true,'textarea')];
case 'boardmeta':return [t('summary','Descrição da frente',true,'textarea'),t('ownerText','Responsáveis (separados por /)',true)];
case 'scope':return [t('offerDefinition','01 · Definição da oferta',true,'textarea'),t('problem','Problema / necessidade que resolvemos',true,'textarea'),t('within','Dentro do recorte',true,'textarea'),t('outside','Fora do recorte',true,'textarea'),t('value','Resultado esperado',true,'textarea')];
case 'offers':return [t('title','Produto / serviço',true),t('detail','O que vamos disponibilizar',true,'textarea'),t('rules','Regras, condições e restrições',true,'textarea'),t('horizon','Horizonte',false,'select',HORIZONS),t('nature','Natureza',false,'select',['Referência do material','Capacidade mapeada','Hipótese de trabalho','Decisão aprovada']),t('status','Situação',false,'select',['Em discussão','A validar','Definido','Fora do recorte']),t('eligibility','Elegibilidade por grupo / condição (a validar)',true,'eligibility'),t('eligibilityNotes','Condi\u00e7\u00f5es ou diferen\u00e7as por grupo',true,'eligibilityNotes')];
case 'journeyStep':return [t('name','Nome da etapa',true),t('client','Jornada / objetivo do cliente',true,'textarea'),t('channel','Canais e atendimento (onde acontece)',true,'textarea'),t('orchestration','Orquestração / fluxo (como acontece)',true,'textarea'),t('capability','Capacidades, sistemas e parceiros (o que habilita)',true,'textarea'),t('data','Dados, integrações e eventos',true,'textarea'),t('nature','Natureza da definição',false,'select',['Hipótese de trabalho','Em validação','Definido'])];
case 'asis':return [t('step','Etapa',true),t('where','Onde acontece (sistema / canal / rotina)',true),t('who','Quem faz (time / ator)',true)];
case 'profiles':return [t('needs','O que esse grupo precisa',true,'textarea'),t('conditions','Condições / elegibilidade',true,'textarea')];
case 'cases':return [t('ref','ID do caso'),t('title','Nome do user case',true),t('profiles','Grupos aos quais se aplica',true,'profiles'),t('audience','Contexto adicional (vida financeira, residência, estrutura)',true),t('need','Necessidade do cliente',true,'textarea'),t('trigger','Gatilho de início',true,'textarea'),t('result','Resultado esperado',true,'textarea'),t('flow','Fluxo principal (etapas)',true,'textarea'),t('variants','Variações por perfil / condição',true,'textarea'),t('exception','Exceções importantes',true,'textarea'),t('channel','Canais envolvidos'),t('operations','Papel da operação',true,'textarea'),t('systems','Sistemas / controles',true,'textarea'),t('horizon','Horizonte',false,'select',HORIZONS),t('status','Status',false,'select',['Rascunho','Em definição','Validado','Fora do recorte']),t('owner','Responsável')];
case 'blueprint':return [t('moment','Momento / etapa da jornada',true),t('clientWhere','Cliente · Onde?',false),t('client','Cliente · O que faz?',true,'textarea'),t('commercialWhere','Comercial · Onde?',false),t('commercial','Comercial · O que faz?',true,'textarea'),t('operationsWhere','Operação · Onde?',false),t('operations','Operação · O que faz?',true,'textarea'),t('systemsWhere','Sistemas e controles · Onde?',false),t('systems','Sistemas e controles · O que faz?',true,'textarea'),t('controls','Regras / controles transversais',true,'textarea')];
case 'csd':return [t('type','Classificação CSD',false,'select',['Certeza','Suposição','Dúvida']),t('priority','Prioridade',false,'select',['Alta','Média','Baixa']),t('stage','Bloco de origem',true,'stage'),t('title','Título da certeza, suposição ou dúvida',true),t('detail','Descrição / pergunta a resolver',true,'textarea'),t('owner','Responsável'),t('deadline','Prazo',false,'date'),t('status','Status',false,'select',['Aberta','Em validação','Em andamento','Registrada','Resolvida']),t('action','Próximo passo / tarefa',true,'textarea'),t('related','Área / dependência'),t('horizon','Horizonte',false,'select',HORIZONS),t('resolution','Resposta / decisão / evidência',true,'textarea'),t('source','Fonte / origem',true)];
case 'actionPlan':return [t('title','A\u00e7\u00e3o / entrega',true),t('detail','O que ser\u00e1 feito?',true,'textarea'),t('acceptance','Crit\u00e9rio de conclus\u00e3o',true,'textarea'),t('owner','Respons\u00e1vel'),t('deadline','Prazo',false,'date'),t('status','Status',false,'select',['N\u00e3o iniciada','Em andamento','Aguardando defini\u00e7\u00e3o','Conclu\u00edda','Cancelada']),t('priority','Prioridade',false,'select',['Alta','M\u00e9dia','Baixa']),t('horizon','Horizonte',false,'select',HORIZONS),t('source','Origem / decis\u00e3o relacionada',true)];
case 'decisions':return [t('title','Decisão a tomar / decisão registrada',true),t('status','Situação da decisão',false,'select',['Em discussão','Em validação','Decisão final','Revogada']),t('detail','Contexto e alternativas consideradas',true,'textarea'),t('rationale','Escolha e justificativa / evidência',true,'textarea'),t('owner','Responsável pela decisão'),t('horizon','Horizonte',false,'select',HORIZONS),t('linkedQuestion','Dúvida / dependência relacionada (opcional)',true),t('reference','Registro, documento ou referência (opcional)',true)];
}return []}
function modalTitle(kind){return ({session:'Configuração do workshop',boardmeta:'Responsáveis e descrição',scope:'Oferta e recorte',offers:'Produto ou serviço',asis:'Etapa AS-IS',profiles:'Grupo de relacionamento',cases:'Caso de uso',blueprint:'Momento da experiência',csd:'Registro CSD',actionPlan:'A\u00e7\u00e3o do plano',decisions:'Decisão'})[kind]||kind}
function editForm(kind,uid='',defaults={}){const b=activeBoard();let rec=kind==='session'?clone(state.session):kind==='boardmeta'?{summary:b.summary,ownerText:b.owners.join(' / ')}:kind==='scope'?clone(b.scope):kind==='journeyStep'?clone((b.journeyMap?.steps||[]).find(x=>x.uid===uid)||defaults):clone(b[kind]?.find(x=>x.uid===uid)||defaults);if(kind==='cases'&&!uid&&view.caseFilter!=='Todos')rec.profiles=[view.caseFilter];const spec=fieldsFor(kind,rec);if(!spec.length)return;currentModal={kind,uid,boardId:b.id};let elems=spec.map(f=>{let value=rec[f.key]??'';let field;if(f.type==='textarea'){field=`<textarea name="${f.key}" rows="3">${esc(value)}</textarea>`}else if(f.type==='select'){let opts=[...(f.options||[])];if(value&&!opts.includes(value))opts.push(value);field=`<select name="${f.key}">${opts.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select>`}else if(f.type==='profiles'){field=`<div class="multi-pick">${RELATIONS.map(p=>`<label><input type="checkbox" name="profiles" value="${esc(p)}" ${Array.isArray(value)&&value.includes(p)?'checked':''}>${esc(p)}</label>`).join('')}</div>`}else if(f.type==='eligibility'){field=`<div class="eligibility-editor">${RELATIONS.map((p,i)=>`<div class="eligibility-editor-row"><strong>${esc(p)}</strong><select name="eligibility_${i}">${['A definir','Elegível','Condicional','Não elegível'].map(v=>`<option value="${v}" ${v===(value?.[p]||'A definir')?'selected':''}>${v}</option>`).join('')}</select></div>`).join('')}</div><small class="dim">A elegibilidade deve ser validada pelas áreas responsáveis. “US Person” pode se sobrepor aos demais grupos.</small>`}else if(f.type==='eligibilityNotes'){field=`<div class="eligibility-editor eligibility-notes-editor">${RELATIONS.map((p,i)=>`<div class="eligibility-editor-row eligibility-note-row"><strong>${esc(p)}</strong><textarea name="eligibility_notes_${i}" rows="2" placeholder="Explique a condi\u00e7\u00e3o, restri\u00e7\u00e3o ou diferen\u00e7a para este perfil">${esc(value?.[p]||'')}</textarea></div>`).join('')}</div><small class="dim">Detalhe o que diferencia cada grupo: elegibilidade, documenta\u00e7\u00e3o, autoriza\u00e7\u00f5es, limites ou regras espec\u00edficas.</small>`}else if(f.type==='stage'){let cur=String(value===''?'Geral':value);field=`<select name="stage"><option value="Geral" ${cur==='Geral'?'selected':''}>Geral / transversal</option>${STAGES.map((x,i)=>`<option value="${i}" ${cur===String(i)?'selected':''}>${String(i+1).padStart(2,'0')} · ${esc(x.name)}</option>`).join('')}</select>`}else{field=`<input type="${f.type==='date'?'date':'text'}" name="${f.key}" value="${esc(value)}" ${f.key==='title'&&kind!=='csd'?'required':''}>`}return `<div class="field ${f.full?'full':''}"><label>${esc(f.label)}</label>${field}</div>`}).join('');const el=document.createElement('div');el.className='modal-layer';el.id='modal-layer';el.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><div class="micro">EDITAR WORKSHOP · ${esc(b.short)}</div><h2 id="modal-title">${uid?'Editar':'Adicionar'} · ${esc(modalTitle(kind))}</h2><p>Preencha com base no que foi discutido. Decisões finais precisam de responsável e justificativa; hipóteses devem permanecer explícitas.</p></div><button type="button" class="modal-close" data-action="close-modal" aria-label="Fechar">×</button></div><form id="modal-form"><div class="form-grid">${elems}</div><div class="modal-foot"><button type="button" class="btn" data-action="close-modal">Cancelar</button><button type="submit" class="btn accent">Salvar alterações</button></div></form></div>`;document.body.appendChild(el);el.querySelector('input:not([type="checkbox"]),textarea,select')?.focus()}
function closeModal(){document.getElementById('modal-layer')?.remove();currentModal=null}
function saveForm(e){e.preventDefault();if(!currentModal)return;let {kind,uid,boardId}=currentModal;let b=boardBy(boardId),fd=new FormData(e.target);let payload={};for(let f of fieldsFor(kind,{}))payload[f.key]=f.type==='profiles'?fd.getAll('profiles'):f.type==='eligibility'?Object.fromEntries(RELATIONS.map((p,i)=>[p,String(fd.get('eligibility_'+i)||'A definir')])):f.type==='eligibilityNotes'?Object.fromEntries(RELATIONS.map((p,i)=>[p,String(fd.get('eligibility_notes_'+i)||'').trim()])):String(fd.get(f.key)||'').trim();if(kind==='decisions'&&payload.status==='Decisão final'&&(!payload.owner||!payload.rationale)){alert('Para registrar uma decisão final, informe o responsável e a justificativa/evidência.');return}if(kind==='session'){Object.assign(state.session,payload)}else if(kind==='boardmeta'){b.summary=payload.summary;b.owners=payload.ownerText.split(/[\/;,]+/).map(x=>x.trim()).filter(Boolean)}else if(kind==='scope'){Object.assign(b.scope,payload)}else if(kind==='journeyStep'){const col=b.journeyMap.steps,idx=col.findIndex(x=>x.uid===uid);if(idx>=0)col[idx]={...col[idx],...payload};else col.push({uid:qid(),...payload})}else{let col=b[kind],idx=col.findIndex(x=>x.uid===uid);if(kind==='cases'&&!payload.ref)payload.ref=b.code+'-UC'+String(col.length+1).padStart(2,'0');if(kind==='csd'&&!payload.status)payload.status=payload.type==='Certeza'?'Registrada':'Aberta';if(kind==='decisions'){let before=idx>=0?clone(col[idx]):null;const now=new Date().toISOString();let record={...before,...payload,uid:before?.uid||qid(),updatedAt:now,decidedAt:payload.status==='Decisão final'?(before?.status==='Decisão final'&&before?.decidedAt||now):before?.decidedAt||''};if(idx>=0)col[idx]=record;else col.push(record);if(!before||JSON.stringify(Object.fromEntries(Object.keys(payload).map(k=>[k,before?.[k]])))!==JSON.stringify(payload)){b.decisionHistory=b.decisionHistory||[];b.decisionHistory.unshift({uid:qid(),decisionUid:record.uid,title:record.title,from:before?.status||'Novo',to:record.status,at:now,owner:record.owner||'',rationale:record.rationale||'',event:before?'Atualização':'Criação'});} }else{if(idx>=0)col[idx]={...col[idx],...payload};else col.push({uid:qid(),...payload})}}closeModal();save();render(true);toast('Registro atualizado.');}
function goTop(){window.scrollTo({top:0,behavior:'instant'})}
function clickHandler(e){let t=e.target.closest('[data-action]');if(!t)return;let act=t.dataset.action,id=t.dataset.id,b=activeBoard();if(act==='launch-expand'){document.querySelectorAll('.lt-entry').forEach(x=>{x.open=true});return}if(act==='launch-collapse'){document.querySelectorAll('.lt-entry').forEach(x=>{x.open=false});return}if(act==='launch-open-board'){view.boardId=id;view.page='board';view.step=-1;view.guideOpen=false;render();goTop();return}if(act==='launch-open-matrix'){view.page='overview';view.macroMode='features';view.macroRelease=t.dataset.phase==='Day-1'?'Atual / Day-1':t.dataset.phase;view.macroAudience='Cliente';render();goTop();return}if(act==='macro-mode'){view.macroMode=t.dataset.mode;render(true);return}if(act==='macro-audience'){view.macroAudience=t.dataset.audience;render(true);return}if(act==='macro-clear'){view.macroRelease='Todos';view.macroTech='Todas';view.macroSearch='';render(true);return}if(act==='feature-details'){featureModal(t.dataset.feature);return}if(act==='close-feature'){document.getElementById('feature-layer')?.remove();return}if(act==='feature-go-board'){document.getElementById('feature-layer')?.remove();view.page='board';view.boardId=id;view.step=-1;view.mapAudience='Todos';view.mapRelease='Todos';render();goTop();return}if(act==='save-feature-link'){const fid=t.dataset.feature,sel=document.getElementById('assign-feature-step');if(!sel)return;b.journeyMap.assignments[fid]=sel.value;document.getElementById('feature-layer')?.remove();save();render(true);toast('Vínculo com a jornada atualizado.');return}if(act==='map-add-step'){editForm('journeyStep','',{name:'Nova etapa',nature:'Hipótese de trabalho'});return}if(act==='map-edit'){editForm('journeyStep',id);return}if(act==='map-remove'){const steps=b.journeyMap.steps,idx=steps.findIndex(x=>x.uid===id);if(idx<0)return;if(!confirm('Excluir esta etapa? As funcionalidades vinculadas ficarão sem etapa, mas não serão apagadas da matriz.'))return;steps.splice(idx,1);for(const k of Object.keys(b.journeyMap.assignments))if(b.journeyMap.assignments[k]===id)b.journeyMap.assignments[k]='';save();render(true);return}if(act==='map-move'){const steps=b.journeyMap.steps,idx=steps.findIndex(x=>x.uid===id),next=idx+Number(t.dataset.dir);if(idx<0||next<0||next>=steps.length)return;const item=steps.splice(idx,1)[0];steps.splice(next,0,item);save();render(true);return}if(act==='navigate'){view.page=t.dataset.page||'overview';view.guideOpen=false;render();goTop();return}if(act==='open-board'){view.boardId=id;view.page='board';view.step=-1;view.caseFilter='Todos';view.search='';view.mapAudience='Todos';view.mapRelease='Todos';view.guideOpen=false;render();goTop();return}if(act==='step'){view.step=Number(t.dataset.index);view.search='';view.caseFilter='Todos';render();goTop();return}if(act==='next-step'||act==='prev-step'){view.step=Math.max(0,Math.min(STAGES.length-1,view.step+(act==='next-step'?1:-1)));view.caseFilter='Todos';view.search='';render();goTop();return}if(act==='toggle-guide'){view.guideOpen=!view.guideOpen;render(true);return}if(act==='edit'){editForm(t.dataset.kind,id||'');return}if(act==='promote-csd'){const x=(b.csd||[]).find(a=>a.uid===id);if(!x)return;editForm('actionPlan','',{title:x.action||('Resolver: '+x.title),detail:x.detail||'',acceptance:x.resolution||'',owner:x.owner||'',deadline:x.deadline||'',priority:x.priority||'Alta',status:'N\u00e3o iniciada',horizon:x.horizon||'A definir',source:'CSD: '+x.title});return}if(act==='add-csd'){editForm('csd','',{type:t.dataset.csdType||'Dúvida',priority:'Alta',status:t.dataset.csdType==='Certeza'?'Registrada':'Aberta',horizon:'A definir',stage:t.dataset.stage??String(view.step)});return}if(act==='filter-profile'){view.caseFilter=id;view.search='';render(true);return}if(act==='delete'){let kind=t.dataset.kind,record=b[kind].find(x=>x.uid===id);if(!record)return;if(!confirm('Excluir "'+(record.title||record.step||record.moment)+'"?'))return;b[kind]=b[kind].filter(x=>x.uid!==id);save();render(true);toast('Registro excluído.');return}if(act==='toggle-plan'){const task=(b.actionPlan||[]).find(x=>x.uid===id);if(!task)return;task.status=t.checked?'Conclu\u00edda':'N\u00e3o iniciada';save();setTimeout(()=>render(true),140);return}if(act==='toggle-task'){const task=b.csd.find(x=>x.uid===id);if(!task)return;task.status=t.checked?'Resolvida':'Aberta';save();setTimeout(()=>render(true),250);return}if(act==='delete-note'){b.notes=b.notes.filter(x=>x.uid!==id);save();render(true);return}if(act==='jump-csd'){view.boardId=t.dataset.board;view.page='board';view.step=4;render();goTop();editForm('csd',id);return}if(act==='focus'){view.focus=!view.focus;render(true);return}if(act==='save-json'){saveToJSON();return}if(act==='reconnect-json'){reconnectJSON();return}if(act==='export-json'){exportJSON();return}if(act==='export-portable'){exportHTML();return}if(act==='export-csv'){exportCSV(t.dataset.what);return}if(act==='import-json'){openJSONFile();return}if(act==='print'){window.print();return}if(act==='reset-all'){if(!confirm('Restaurar o template? Isso apagará as alterações salvas neste navegador.'))return;if(!confirm('Tem certeza? Exporte um backup JSON antes de continuar, caso necessário.'))return;state=eState();jsonFileHandle=null;knownFileHandle=null;jsonFileName='';jsonHasExport=false;jsonReconnectNeeded=false;linkedHandleOperation('delete');save();view.page='overview';view.boardId='onboarding';render();goTop();toast('Template restaurado.');return}if(act==='close-modal'){closeModal();return}}
function onSubmit(e){if(e.target?.id==='modal-form'){saveForm(e);return}if(e.target?.id==='note-form'){e.preventDefault();let text=e.target.elements.note?.value.trim();if(!text)return;activeBoard().notes.push({uid:qid(),stage:view.step,text,ts:new Date().toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})});save();render(true);toast('Anotação registrada.')}}
function onChange(e){if(e.target.id==='launch-filter'){view.launchFilter=e.target.value;render(true);return}if(e.target.id==='journey-map-status'){activeBoard().journeyMap.status=e.target.value;save();render(true);return}if(e.target.id==='macro-release'){view.macroRelease=e.target.value;render(true);return}if(e.target.id==='macro-tech'){view.macroTech=e.target.value;render(true);return}if(e.target.id==='board-map-audience'){view.mapAudience=e.target.value;render(true);return}if(e.target.id==='board-map-release'){view.mapRelease=e.target.value;render(true);return}if(e.target.id==='stage-progress'){activeBoard().progress[view.step]=Number(e.target.value);save();render(true);toast('Status da etapa atualizado.')}if(e.target.id==='owner-filter'){view.ownerFilter=e.target.value;render(true)}if(e.target.id==='csd-filter'){view.csdFilter=e.target.value;render(true)}}
function onInput(e){if(e.target.id==='macro-search'){view.macroSearch=e.target.value;const query=view.macroSearch.toLowerCase();let total=0;document.querySelectorAll('.macro-column').forEach(col=>{let n=0;col.querySelectorAll('.matrix-feature').forEach(el=>{const ok=(el.dataset.query||'').includes(query);el.hidden=!ok;if(ok)n++});const count=col.querySelector('.col-count');if(count)count.textContent=n;total+=n});const counter=document.getElementById('matrix-count');if(counter)counter.textContent=total+' resultados';return}if(e.target.id==='case-search'){view.search=e.target.value;let cards=[...document.querySelectorAll('#case-list .case-card')],count=0;for(const c of cards){const show=c.dataset.query.includes(view.search.toLowerCase());c.hidden=!show;if(show)count++}let label=document.getElementById('cases-count');if(label)label.textContent=count}}


const OFFSHORE_FILE_DB='offshore_workshop_json_files_v9';
function openHandleDB(){return new Promise((resolve,reject)=>{if(!('indexedDB' in window))return reject(new Error('IndexedDB indispon\u00edvel'));const req=indexedDB.open(OFFSHORE_FILE_DB,1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('handles'))req.result.createObjectStore('handles')};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function linkedHandleOperation(mode,handle){try{const db=await openHandleDB();return await new Promise((resolve,reject)=>{const tx=db.transaction('handles',mode==='read'?'readonly':'readwrite'),store=tx.objectStore('handles'),req=mode==='read'?store.get(instance):mode==='delete'?store.delete(instance):store.put(handle,instance);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);tx.oncomplete=()=>db.close();tx.onerror=()=>reject(tx.error)})}catch(e){console.warn('V\u00ednculo JSON indispon\u00edvel',e);return null}}
async function filePermission(handle,mode){try{const opts={mode};const status=await handle.queryPermission?.(opts);if(status==='granted'||typeof handle.queryPermission!=='function')return true;return (await handle.requestPermission?.(opts))==='granted'}catch(e){return false}}
function jsonFileTypes(){return [{description:'Dados do workshop (JSON)',accept:{'application/json':['.json']}}]}
function jsonFilename(){return jsonFileName||'novas_jornadas_offshore_dados.json'}
async function saveToJSON(){const body=JSON.stringify(state,null,2);try{if(jsonFileHandle||typeof window.showSaveFilePicker==='function'){let handle=jsonFileHandle;if(!handle)handle=await window.showSaveFilePicker({suggestedName:jsonFilename(),types:jsonFileTypes()});if(!(await filePermission(handle,'readwrite')))throw new Error('Sem permiss\u00e3o de grava\u00e7\u00e3o');const writer=await handle.createWritable();try{await writer.write(body);await writer.close()}catch(e){try{await writer.abort()}catch(x){}throw e}jsonFileHandle=handle;knownFileHandle=handle;jsonReconnectNeeded=false;await linkedHandleOperation('write',handle);markJSONSynchronized(handle.name||jsonFilename());toast('JSON salvo. As pr\u00f3ximas grava\u00e7\u00f5es atualizam o mesmo arquivo.');return}}catch(err){if(err?.name==='AbortError')return;console.warn('Grava\u00e7\u00e3o direta indispon\u00edvel',err)}download(body,jsonFilename(),'application/json;charset=utf-8');jsonFileHandle=null;markJSONSynchronized(jsonFilename());toast('JSON baixado. Reabra o arquivo na pr\u00f3xima sess\u00e3o para continuar.');}
function applyOpenedJSON(raw,name,handle=null,ask=true){const validationError=validateStateInput(raw);if(validationError)throw new Error('Formato de dados não reconhecido. '+validationError);const incoming=normalizeState(raw);if(!incoming)throw new Error('Formato de dados n\u00e3o reconhecido.');if(ask&&jsonDirty&&!confirm('Existem altera\u00e7\u00f5es ainda n\u00e3o salvas no JSON. Deseja substitu\u00ed-las pelos dados do arquivo selecionado?'))return false;state=incoming;jsonFileHandle=handle;knownFileHandle=handle;jsonReconnectNeeded=false;markJSONSynchronized(name);view.page='overview';view.boardId='onboarding';view.step=-1;view.guideOpen=false;render();goTop();toast(handle?'JSON conectado. Salvar atualizar\u00e1 esse arquivo.':'JSON carregado. Use Salvar JSON para gravar uma nova c\u00f3pia.');return true}
async function openJSONFile(){if(typeof window.showOpenFilePicker==='function'){try{const [h]=await window.showOpenFilePicker({types:jsonFileTypes(),multiple:false});const f=await h.getFile();const success=applyOpenedJSON(JSON.parse(await f.text()),f.name,h);if(success)await linkedHandleOperation('write',h);return}catch(e){if(e?.name==='AbortError')return;if(e instanceof SyntaxError||/Formato de dados/.test(e.message)){alert('N\u00e3o foi poss\u00edvel abrir o JSON: '+e.message);return}console.warn('Seletor nativo indispon\u00edvel',e)}}document.getElementById('import-file').click()}
async function startupLinkedFile(){const h=await linkedHandleOperation('read');if(!h||typeof h.getFile!=='function')return;knownFileHandle=h;jsonFileName=h.name||jsonFileName;let permission='prompt';try{permission=await h.queryPermission({mode:'read'})}catch(e){}if(permission!=='granted'||jsonDirty){jsonReconnectNeeded=true;render(true);return}try{const f=await h.getFile();const valid=normalizeState(JSON.parse(await f.text()));if(!valid)throw new Error('JSON inv\u00e1lido');state=valid;jsonFileHandle=h;jsonReconnectNeeded=false;markJSONSynchronized(f.name);render(true)}catch(e){jsonReconnectNeeded=true;render(true);console.warn('Reconex\u00e3o pendente',e)}}
async function reconnectJSON(){if(!knownFileHandle)return openJSONFile();try{if(!(await filePermission(knownFileHandle,'read')))throw new Error('Permiss\u00e3o de leitura n\u00e3o concedida');const f=await knownFileHandle.getFile();const ok=applyOpenedJSON(JSON.parse(await f.text()),f.name,knownFileHandle);if(ok)await linkedHandleOperation('write',knownFileHandle)}catch(e){alert('N\u00e3o foi poss\u00edvel reconectar o arquivo: '+e.message)}}

function download(content,filename,mime){let url=URL.createObjectURL(new Blob([content],{type:mime})),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),6000)}
function exportJSON(){download(JSON.stringify(state,null,2),'novas_jornadas_offshore_backup.json','application/json;charset=utf-8');toast('Cópia JSON baixada.')}
function exportHTML(){const root=document.documentElement.cloneNode(true);const snapshot=root.querySelector('#portable-state');if(!snapshot)return;let newInstance=qid();snapshot.dataset.instance=newInstance;snapshot.textContent=JSON.stringify(state).replace(/</g,'\\u003c');const holder=root.querySelector('#app');if(holder)holder.innerHTML='';root.querySelectorAll('#modal-layer,#bp-dialog,#feature-layer,.toast').forEach(el=>el.remove());download('<!DOCTYPE html>\n'+root.outerHTML,'novas_jornadas_offshore_v18_preenchido.html','text/html;charset=utf-8');toast('HTML preenchido exportado. Abra esse arquivo para retomar a sessão.')}
function csvCell(s){let v=String(s??'');if(/^[=+@-]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"'}
function exportCSV(what){let headings=[],rows=[];if(what==='cases'){headings=['Frente','Responsáveis','ID','Caso','Perfis','Outros contextos','Necessidade','Gatilho','Resultado','Fluxo','Exceções','Canal','Horizonte','Status','Dono'];for(let b of state.boards)for(let x of b.cases)rows.push([b.name,printOwners(b),x.ref,x.title,(x.profiles||[]).join(' / '),x.audience,x.need,x.trigger,x.result,x.flow,x.exception,x.channel,x.horizon,x.status,x.owner])}else if(what==='csd'){headings=['Frente','Responsáveis da frente','CSD','Título','Etapa','Detalhe','Responsável','Prazo','Próxima ação','Prioridade','Status','Horizonte','Resolução','Fonte'];for(let b of state.boards)for(let x of b.csd)rows.push([b.name,printOwners(b),x.type,x.title,x.stage??'Geral',x.detail,x.owner,x.deadline,x.action,x.priority,x.status,x.horizon,x.resolution,x.source])}else if(what==='actions'){headings=['Frente','Respons\u00e1veis da frente','A\u00e7\u00e3o','Descri\u00e7\u00e3o','Crit\u00e9rio de conclus\u00e3o','Respons\u00e1vel','Prazo','Status','Prioridade','Horizonte','Origem'];for(let b of state.boards)for(let x of b.actionPlan||[])rows.push([b.name,printOwners(b),x.title,x.detail,x.acceptance,x.owner,x.deadline,x.status,x.priority,x.horizon,x.source])}else{headings=['Frente','Responsáveis','Cobertura de campos (%)','Etapas validadas','Total de etapas','Casos de uso','Decisões finais','Dúvidas abertas'];rows=state.boards.map(b=>[b.name,printOwners(b),completion(b).ratio,validated(b),V10_TABS.length,b.cases.length,finalDecisions(b).length,openTasks(b).length])}download('\ufeff'+[headings,...rows].map(a=>a.map(csvCell).join(';')).join('\r\n'),'workshop_offshore_'+what+'.csv','text/csv;charset=utf-8');toast('CSV exportado.')}
function importFile(e){const file=e.target.files?.[0];if(!file)return;file.text().then(s=>{try{applyOpenedJSON(JSON.parse(s),file.name,null)}catch(err){alert('N\u00e3o foi poss\u00edvel importar o JSON: '+err.message)}}).finally(()=>{e.target.value=''})}

